INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3587', 'spa', 'rapar, cortar el cabello al ras de la piel con navaja', 'Rapar es quitar el cabello cortándolo al ras de la piel. Pablo aconseja a cuatro hombres que se «rapen la cabeza» como parte de la purificación de un voto nazareo (Hch 21:24). Argumenta que si una mujer ora con la cabeza descubierta, bien podría «raparse» (1 Co 11:5-6), algo culturalmente vergonzoso. El término es literal: remoción del cabello. El griego ξυράω/ξυρέω es la palabra estándar para el afeitado con navaja, ya sea por motivos rituales o como señal de deshonra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3588', 'spa', 'El artículo definido; también sustantivizador, conectivo y marcador comparativo en todos los casos y géneros', 'La palabra más frecuente del Griego del Nuevo Testamento, apareciendo más de 20,000 veces. Mucho más que un simple ''el/la/lo,'' organiza el discurso griego en todos los niveles—marcando definitud, convirtiendo adjetivos y participios en sustantivos (''el que cree''), estructurando genealogías y listas (el artículo repetido en Mateo 1), y señalando relaciones de caso. Su flexibilidad le permite funcionar como casi-pronombre, conector discursivo, e incluso marcador comparativo. Cada lengua meta lo maneja diferente: el alemán preserva inflexión de caso completa (der/die/das/den/dem/des), el español lo fusiona con preposiciones (al, del), mientras que muchas lenguas asiáticas lo omiten completamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3590', 'spa', 'Octavo; el número ordinal ocho, aplicado a días, personas y elementos en una secuencia', 'Adjetivo ordinal que significa ''octavo'', usado en el NT para indicar un día (Lc 1:59, la circuncisión de Juan el Bautista al octavo día), una persona en una secuencia genealógica (2 P 2:5, Noé como la ''octava'' persona preservada), una posición en una serie de reyes (Ap 17:11) y una piedra de cimiento (Ap 21:20). Las traducciones en distintos idiomas son ordinales numéricos directos que reflejan la claridad universal del concepto. En español, ''octavo'' cubre todos estos usos sin ambiguedad alguna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3591', 'spa', 'Volumen, masa o peso que estorba; algo pesado que obstaculiza el movimiento o el progreso', 'Aunque en griego clásico esta palabra puede denotar volumen físico o masa, su uso en el Nuevo Testamento en Hebreos 12:1 es metafórico: ''despojémonos de todo peso y del pecado que nos asedia''. Aquí ''peso'' se refiere a las cargas que ralentizan la carrera cristiana, no necesariamente al pecado en sí, sino a impedimentos legítimos que sin embargo entorpecen el progreso espiritual. La imagen atlética es vívida: los corredores se despojaban de toda ropa y peso innecesario para correr sin trabas. Los traductores emplean consistentemente ''peso'' o ''carga'', reconociendo la fuerza de la metáfora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3592', 'spa', 'Este, esta, estos, estas — pronombre demostrativo de cercanía que señala lo que está presente, lo recién mencionado o lo que está a punto de declarars', 'Este, esta, estos, estas — pronombre demostrativo de cercanía que señala lo que está presente, lo recién mencionado o lo que está a punto de declararse. El pronombre demostrativo ὅδε (hode) significa ''este'' o ''estos,'' señalando algo presente en el contexto inmediato o que va a especificarse a continuación. Es menos frecuente que el más común οὗτος y posee un registro algo formal u oracular. En Apocalipsis introduce las palabras de Cristo a cada iglesia: ''Esto dice el que...'' (Ap 2:1, 8, 12, 18; 3:1, 7, 14). En Hch 21:11 el profeta Ágabo declara: ''Esto dice el Espíritu Santo.'' Santiago 4:13 lo usa para un plan hipotético: ''iremos a tal o cual ciudad.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3593', 'spa', 'Quien viaja o transita por un camino; un caminante que realiza un trayecto', 'Este participio describe a alguien que se encuentra activamente en viaje, transitando por un camino. En Lucas 10:33, introduce al samaritano en la parábola de Jesús: ''Pero un samaritano que iba de camino llegó adonde estaba el hombre''. La palabra enfatiza movimiento y travesía: el samaritano no simplemente pasaba de forma abstracta, sino que estaba viajando activamente, y aun así se detuvo a ayudar. El griego clásico emplea este término para quienes atraviesan territorios, y el Nuevo Testamento conserva ese sentido de desplazamiento deliberado por una ruta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3594', 'spa', 'Guiar, conducir por el camino; dirigir a alguien física o espiritualmente hacia un destino o verdad', 'Verbo que significa guiar o conducir a alguien por un camino, derivado de ὁδός (camino) + ἡγέομαι (dirigir). Posee sentidos tanto literales como metafóricos en el NT. En Mt 15:14 y Lc 6:39, guías ciegos conducen a otros a un hoyo. En Jn 16:13, el Espíritu de verdad ''os guiará a toda la verdad''. En Hch 8:31, el eunuco etíope pide a Felipe que lo guíe en la comprensión de las Escrituras. La raíz ὁδός le confiere un fuerte sentido direccional: no se trata de mera influencia, sino de conducir activamente a alguien hacia una meta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3595', 'spa', 'Guía, conductor; quien dirige a otros por un camino, frecuentemente en sentido metafórico de maestros religiosos', 'Sustantivo que significa guía o conductor: aquel que muestra el camino. En los Evangelios, Jesús lo emplea de manera incisiva contra los fariseos: ''guías ciegos'' (Mt 15:14; 23:16, 24) que extravían a otros a pesar de afirmar conocer la senda. Hechos 1:16 lo aplica a Judas como ''guía'' de quienes arrestaron a Jesús. En Ro 2:19, Pablo cita la autocomprensión judía de ser ''guía de los ciegos''. Las cinco apariciones neotestamentarias llevan fuertes matices metafóricos de liderazgo religioso o moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3596', 'spa', 'Viajar, hacer un recorrido o emprender un trayecto; caminar o avanzar por un camino', 'Este verbo significa viajar o hacer un recorrido, particularmente a pie. En Hechos 10:9, establece el escenario para la visión de Pedro: ''mientras ellos iban de camino y se acercaban a la ciudad''. La palabra enfatiza el proceso del viaje más que el simple movimiento: estos mensajeros estaban en una travesía deliberada con un destino definido. El uso clásico incluye el desplazamiento a través de territorios o la llegada a un lugar. Las traducciones multilingües mantienen el sentido de movimiento intencional hacia una meta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3598', 'spa', 'Camino, senda, vía; ruta física, curso figurado de vida o conducta, o ''el Camino'' como movimiento cristiano primitivo', 'Pocas palabras del Nuevo Testamento portan tanta carga teológica como ὁδός. En su sentido más sencillo designa un camino físico — la ruta a Emaús, el camino de Jerusalén a Jericó. Pero pronto se convierte en la gran metáfora bíblica de la vida, la conducta y el destino: Juan el Bautista prepara ''el camino del Señor'' (Mt 3:3), Jesús declara ''yo soy el camino'' (Jn 14:6), y los caminos ancho y estrecho definen dos destinos últimos (Mt 7:13-14). Lo más notable es que los primeros cristianos llamaban a su movimiento simplemente ''el Camino'' (Hch 9:2; 19:9, 23), antes de que se impusiera el nombre ''cristiano''. Español camino replica este mismo arco de lo literal a lo figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3599', 'spa', 'ὀδούς: diente; estructura ósea dura en la mandíbula, frecuentemente en la expresión ''crujir de dientes''. El sustantivo ὀδούς (''diente'') designa la est', 'ὀδούς: diente; estructura ósea dura en la mandíbula, frecuentemente en la expresión ''crujir de dientes''. El sustantivo ὀδούς (''diente'') designa la estructura ósea dura enraizada en la mandíbula, usada para morder y masticar. Aunque la palabra tiene un significado anatómico directo, su perfil neotestamentario está dominado por una fórmula vívida: βρυγμὸς τῶν ὀδόντων, ''crujir de dientes'', que Jesús emplea repetidamente para representar la angustia y la furia del juicio escatológico (Mt 8:12; 13:42, 50; 22:13; 24:51; 25:30; Lc 13:28). El único otro contexto es la cita de la ley del talión ''diente por diente'' (Mt 5:38), tomada de Éxodo 21:24.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3600', 'spa', 'Sufrir angustia, padecer dolor o tormento; afligirse profundamente', 'Expresa un sufrimiento intenso que puede ser físico, emocional o ambos. En Lc 16:24-25, el hombre rico clama desde el Hades que está ''atormentado'' en las llamas, el uso más visceralmente físico. Sin embargo, en Lc 2:48, María dice al niño Jesús que ella y José lo han buscado ''con gran angustia'', y en Hch 20:38, los ancianos de Éfeso se afligen profundamente porque nunca más verán el rostro de Pablo. La palabra tiende así un puente entre el tormento corporal y la angustia emocional, abarcando desde el sufrimiento físico hasta el dolor del alma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3603', 'spa', 'ser, estar, existir (verbo copulativo εἰμί); paradigma muy irregular con variantes dialectales', 'El verbo más fundamental del griego, εἰμί, expresa existencia, identidad y predicación. Su paradigma es enormemente irregular y proviene de múltiples raíces antiguas: presente εἰμί, imperfecto ἦν, futuro ἔσομαι. Abundan las formas dialectales: eólico ἔμμι, dórico ἐντί, épico εἰμέν. La tercera persona ἐστί puede tener valor existencial («hay»), copulativo («el hombre es sabio») o posesivo («tengo» = μοί ἐστι). Ningún otro verbo griego se usa con tanta frecuencia ni presenta mayor irregularidad morfológica a lo largo de los dialectos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3605', 'spa', 'Emitir un olor o aroma, ya sea agradable o desagradable; despedir un hedor o fragancia', 'Este verbo griego significa oler o despedir un olor, ya sea una fragancia agradable o un hedor repulsivo, dependiendo del contexto. El Nuevo Testamento lo emplea una sola vez de manera impactante: en Juan 11:39, Marta se opone a abrir la tumba de Lázaro con las crudas palabras: «Señor, ya hiede, porque lleva cuatro días muerto». El verbo transmite la cruda realidad de la descomposición corporal. Los traductores suelen verterlo como «hiede» o «apesta», sin suavizar el hecho físico que hace el milagro de resurrección de Jesús aún más asombroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3606', 'spa', 'De donde, desde donde (origen espacial); por extensión, por lo cual, por esa razón (conectivo inferencial). Este adverbio compacto conecta el espacio ', 'De donde, desde donde (origen espacial); por extensión, por lo cual, por esa razón (conectivo inferencial). Este adverbio compacto conecta el espacio físico con el razonamiento lógico en el Nuevo Testamento. En su sentido espacial, ὅθεν pregunta ''¿de dónde?'': como cuando un espíritu inmundo regresa a la casa ''de donde'' salió (Mt 12:44; Lc 11:24), o un amo cosecha ''donde'' no sembró (Mt 25:24). Pero especialmente en Hebreos, ὅθεν se desplaza hacia un marcador inferencial que significa ''por lo cual'' o ''por esa razón'' (He 2:17; 3:1; 7:25; 8:3), extrayendo conclusiones teológicas con precisión lógica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3608', 'spa', 'Lienzo funerario, tira de lino; vendas de lino usadas especialmente para la sepultura, los lienzos que envolvieron el cuerpo de Jesus.', 'Diminutivo de ὀθόνη (lino), que designa tiras o piezas de tela de lino. Las cinco apariciones en el Nuevo Testamento se relacionan directamente con la sepultura y resurreccion de Jesus. En Juan 19:40, el cuerpo es envuelto en lienzos con especias aromaticas segun la costumbre judia. El hallazgo de estos mismos lienzos en la tumba vacia se convierte en evidencia poderosa de la resurreccion (Lucas 24:12; Juan 20:5-7). La forma diminutiva sugiere tiras o piezas pequenas, a diferencia de la sabana grande designada por σινδών.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3609', 'spa', 'Miembros de la casa o familia; los que pertenecen a un hogar o círculo doméstico', 'Los οἰκεῖοι son quienes pertenecen a una casa o familia, vinculados por parentesco o asociación. Pablo exhorta a hacer el bien «especialmente a los de la familia de la fe» (Gá 6:10). En Efesios 2:19, los creyentes gentiles ya no son extraños sino «miembros de la familia de Dios». Primera Timoteo 5:8 advierte que quien no provee para los suyos ha negado la fe. El término subraya el vínculo de pertenencia y la obligación relacional dentro del hogar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3610', 'spa', 'Siervo domestico, esclavo del hogar; miembro de una casa que sirve bajo la autoridad de su amo.', 'Sustantivo derivado de οἶκος (casa) que designa a un siervo perteneciente a un hogar, con un matiz mas intimo que el generico δοῦλος (esclavo). En Mateo 24:45 (el siervo fiel y prudente puesto sobre la casa) y Lucas 16:13 (ningun siervo puede servir a dos senores), el termino evoca la relacion cercana y de confianza entre amo y sirviente domestico. Hechos 10:7 describe a los piadosos siervos domesticos de Cornelio, y 1 Pedro 2:18 se dirige directamente a estos esclavos del hogar, exhortandolos a la sumision.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3611', 'spa', 'Habitar, morar, residir; usado tanto de la habitación física como de la morada espiritual del pecado o del Espíritu Santo.', 'Derivado de οἶκος (casa), este verbo significa habitar o residir en un lugar. Aunque su sentido básico es residencial, Pablo lo transforma en Romanos 7-8 en una poderosa metáfora teológica. El pecado «habita en» la carne del creyente (Ro 7:17, 18, 20), pero el Espíritu de Dios también «habita en» quienes pertenecen a Cristo (Ro 8:9, 11). Esta tensión entre el pecado que mora en nosotros y el Espíritu que mora en nosotros es central en la antropología paulina. El español «habitar» deriva del latín habitare, conservando la misma metáfora doméstica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3612', 'spa', 'Lugar de habitación o aposento; específicamente una celda, cámara o lugar de reclusión como una celda de prisión', 'Este sustantivo griego designa una habitación o morada, con un uso clásico que abarca desde dormitorios hasta almacenes y celdas de prisión. En Hechos 12:7, describe el lugar donde Pedro estaba encarcelado: «una luz resplandeció en la celda». El contexto deja claro que se trata de una celda de prisión donde Pedro dormía encadenado entre dos guardias. Aunque la palabra puede significar cualquier habitación o aposento, la narración de Lucas la define como un lugar de reclusión, escenario del milagroso rescate angélico de Pedro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3614', 'spa', 'Casa o vivienda como estructura física; por metonimia, hogar o las personas que habitan en una casa', 'οἰκία designa una casa o vivienda física —el edificio donde se habita, se come y se reúne la comunidad—. Jesús construye su parábola de los dos constructores en torno a la οἰκία edificada sobre roca o sobre arena (Mt 7:24-27), y los magos entran en la οἰκία para encontrar al niño Jesús (Mt 2:11). Por extensión metonímica, el término puede referirse al hogar, es decir, a las personas que componen una unidad familiar. Pablo elogia a la casa de Estéfanas como primicias de Acaya (1 Co 16:15), y envía saludos a los de la casa de César (Fil 4:22). El español «casa» abarca ambos sentidos, dejando al contexto la desambiguación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3616', 'spa', 'Administrar o gobernar un hogar; ejercer autoridad sobre los asuntos domésticos como cabeza de familia', 'Este verbo significa ser amo o señor de un hogar, administrando sus asuntos y ejerciendo autoridad sobre sus miembros. En 1 Timoteo 5:14, Pablo instruye a las viudas jóvenes a «casarse, criar hijos, gobernar su casa», sin dar al adversario ocasión de maledicencia. El término implica un liderazgo doméstico integral: supervisión económica, relacional y espiritual. El griego clásico lo emplea para la administración y la gobernanza. La expresión «gobernar casa» capta tanto la dimensión administrativa como la de autoridad en la responsabilidad del hogar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3617', 'spa', 'οἰκοδεσπότης: dueño de casa, amo del hogar; aquel que posee y administra una casa. Este sustantivo compuesto une οἶκος (''casa'') y δεσπότης (''señor'') p', 'οἰκοδεσπότης: dueño de casa, amo del hogar; aquel que posee y administra una casa. Este sustantivo compuesto une οἶκος (''casa'') y δεσπότης (''señor'') para designar a la persona que posee y ejerce autoridad sobre un hogar y sus asuntos. Aparece exclusivamente en los Evangelios Sinópticos, donde Jesús lo emplea en parábolas y enseñanzas para ilustrar la soberanía divina, la mayordomía vigilante y la relación entre Dios y su pueblo. El dueño de casa que contrata obreros a distintas horas (Mt 20:1), el amo cuyos siervos deben estar alerta (Mr 13:35), el propietario que saca de su tesoro cosas nuevas y viejas (Mt 13:52): cada uno se apoya en la realidad cultural del paterfamilias para transmitir verdades teológicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3618', 'spa', 'Edificar, construir; en sentido figurado, fortalecer o edificar espiritualmente; como sustantivo, constructor', 'Edificar, construir; en sentido figurado, fortalecer o edificar espiritualmente; como sustantivo, constructor');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3619', 'spa', 'Οἰκοδομή tiende un puente entre lo físico y lo espiritual con elegante franqueza. Formada a partir de οἶκος (''casa'') y la raíz de δέμω (''construir''), ', 'Οἰκοδομή tiende un puente entre lo físico y lo espiritual con elegante franqueza. Formada a partir de οἶκος (''casa'') y la raíz de δέμω (''construir''), puede significar tanto una estructura concreta como el proceso abstracto de edificar una comunidad o persona. Pablo hace de esta palabra una piedra angular de su eclesiología: todo en el culto debe apuntar a la οἰκοδομή de la iglesia (1 Co 14:3, 5, 12, 26), y los creyentes deben buscar lo que edifica al prójimo (Ro 14:19; 15:2). El sentido concreto aparece en los Evangelios Sinópticos, donde los discípulos admiran los magníficos edificios del Templo (Mt 24:1; Mc 13:1-2), y en la imagen paulina de un ''edificio de Dios'' celestial que espera a los creyentes (2 Co 5:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3620', 'spa', 'edificación (acto de construir); edificio, estructura construida', 'El sustantivo οἰκοδομία posee dos sentidos relacionados: el proceso de construir (la obra de construcción) y el resultado de ese proceso (un edificio o estructura). Deriva de οἰκοδομέω, «construir una casa», y comparte la ambigüedad entre acción y producto propia de los sustantivos en -ία. En extensión metafórica, puede referirse a la edificación o fortalecimiento espiritual, aunque ese sentido teológico se desarrolla con mayor plenitud en el uso neotestamentario que en los contextos clásicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3621', 'spa', 'Administrar o gestionar como mayordomo; supervisar los asuntos de una casa o hacienda en nombre de otro', 'Este verbo significa administrar o gestionar, particularmente en el papel de mayordomo (οἰκονόμος) que supervisa la propiedad o el hogar de otro. En Lucas 16:2, el amo confronta a su mayordomo: «Da cuenta de tu mayordomía, porque ya no podrás administrar mis bienes». La palabra implica autoridad y responsabilidad delegadas: el mayordomo no es dueño de los recursos, pero debe administrarlos fielmente. En el uso clásico incluye la gestión de cargos públicos y la regulación de recursos, temas centrales en las parábolas de Jesús sobre la mayordomía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3622', 'spa', 'Mayordomía, administración, gestión; la supervisión de una casa o hacienda, extendida al plan redentor de Dios.', 'Derivado de οἰκονόμος (administrador del hogar), este sustantivo abarca tanto el oficio práctico de gestionar una hacienda como el grandioso concepto teológico del plan divino administrado a través de los siglos. En Lucas 16:2-4 se refiere concretamente al puesto de administración de un mayordomo, que puede otorgarse o retirarse. Pablo luego amplía el término de manera notable: se le ha confiado una ''mayordomía'' del evangelio (1 Co 9:17), y la ''administración'' cósmica de Dios alcanza su plenitud en Cristo, unificando todas las cosas en el cielo y en la tierra (Ef 1:10; 3:9). El español ''administración'' capta bien el sentido gerencial del vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3623', 'spa', 'Mayordomo, administrador — persona a quien se confía la administración de una casa, hacienda o responsabilidad espiritual en nombre de otro. El οἰκονό', 'Mayordomo, administrador — persona a quien se confía la administración de una casa, hacienda o responsabilidad espiritual en nombre de otro. El οἰκονόμος es un administrador o mayordomo doméstico que ejerce autoridad delegada sobre los bienes o asuntos de otro. En las parábolas de Lucas, el término describe tanto al mayordomo fiel a quien el amo pone al frente de su casa (12:42) como al mayordomo astuto pero deshonesto que debe rendir cuentas (16:1-8). Pablo extiende la metáfora al liderazgo espiritual: los apóstoles son ''administradores de los misterios de Dios'' (1 Co 4:1-2), y un obispo debe ser ''irreprochable como administrador de Dios'' (Tit 1:7). En Ro 16:23, Erasto el οἰκονόμος de la ciudad designa a un tesorero municipal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3624', 'spa', 'Casa, morada; por extensión, familia o linaje como unidad social', 'Uno de los sustantivos más frecuentes del Nuevo Testamento, οἶκος abarca lo concreto y lo social. En su sentido más básico designa un edificio físico: la casa a la que uno regresa, el templo llamado «casa de mi Padre», la estructura edificada sobre roca o arena. Pero la misma palabra se extiende sin fisuras a las personas que habitan en ella: un hogar, un linaje, «la casa de Israel». El español «casa» reproduce con naturalidad esta doble dimensión, del espacio físico a la comunidad humana que lo ocupa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3625', 'spa', 'El mundo habitado; la tierra civilizada y poblada, frecuentemente referida al Imperio Romano o a toda la humanidad. Originalmente significando ''la (ti', 'El mundo habitado; la tierra civilizada y poblada, frecuentemente referida al Imperio Romano o a toda la humanidad. Originalmente significando ''la (tierra) habitada'' con un γῆ (''tierra'') implícito, esta palabra se expandió desde el mundo de habla griega hasta abarcar toda la tierra poblada, y en tiempos romanos frecuentemente representaba al Imperio mismo. Lucas la usa para el censo que llevó a María y José a Belén (Lc 2:1) y para una hambruna predicha en todo el mundo (Hch 11:28). En contextos escatológicos describe el alcance de la tribulación y la proclamación del evangelio: ''Será predicado este evangelio del reino en toda la οἰκουμένη'' (Mt 24:14). La palabra también tiene un sentido de era futura en Hebreos 2:5, donde el ''mundo venidero'' es sometido a Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3626', 'spa', 'Que permanece en el hogar, dedicada a las labores domésticas; hacendosa o ama de casa', 'Este adjetivo describe a quien permanece en el hogar o se dedica al trabajo doméstico, empleado particularmente para mujeres que administran los asuntos de la casa. En Tito 2:5, Pablo instruye a las mujeres mayores a enseñar a las más jóvenes a ser «prudentes, castas, hacendosas, bondadosas». El contexto cultural es esencial: en el mundo antiguo, la administración del hogar era económicamente vital y moralmente valorada, no trivializada. El término puede traducirse como «hacendosas», «dedicadas al hogar» o «amas de casa», enfatizando el trabajo diligente en el hogar más que la mera ubicación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3628', 'spa', 'Compasion, misericordia, tiernos sentimientos de piedad; cuidado emocional profundo expresado como accion misericordiosa.', 'Sustantivo que expresa compasion profunda y sentimiento misericordioso, frecuente en plural para denotar la plenitud de las tiernas misericordias. Pablo invoca ''las misericordias de Dios'' como fundamento de su exhortacion etica en Romanos 12:1, y llama al Padre ''Dios de toda consolacion'' en 2 Corintios 1:3. Filipenses 2:1 lo empareja con el amor como motivo de unidad. La forma plural οἰκτιρμοί sugiere la totalidad del sentir compasivo, un movimiento visceral que impulsa a actuar con misericordia hacia el projimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3629', 'spa', 'Misericordioso, compasivo; que muestra piedad y bondad activa hacia los necesitados', 'Este adjetivo describe a quien muestra compasión y piedad activa, especialmente hacia los que sufren o están en necesidad. Jesús ordena: «Sed misericordiosos, como también vuestro Padre es misericordioso» (Lc 6:36, repetido para dar énfasis). Santiago presenta al Señor como «compasivo y misericordioso» (Stg 5:11). El término no se refiere a un mero sentimiento, sino a una compasión que se traduce en acción concreta. El griego οἰκτίρμων, derivado de οἶκτος (piedad), apunta a una conmoción visceral ante el dolor ajeno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3631', 'spa', 'Vino; jugo de uva fermentado, la bebida comun del mundo mediterraneo antiguo', 'Vino; jugo de uva fermentado, la bebida comun del mundo mediterraneo antiguo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3632', 'spa', 'Consumo excesivo de vino; embriaguez o intoxicación producida por la ingesta desmedida de vino', 'Este sustantivo designa la embriaguez causada específicamente por el vino (οἶνος), distinguiéndola de otras formas de intoxicación. En 1 Pedro 4:3 aparece dentro de un catálogo de vicios que describen la vida anterior de los gentiles: «viviendo en sensualidad, pasiones, borracheras, orgías y banquetes desenfrenados». El término enfatiza el exceso habitual más que un episodio aislado de indulgencia. En el griego clásico se empleaba para referirse al consumo de vino hasta el punto de la embriaguez. Pedro contrasta ese pasado pagano con la vida cristiana sobria y disciplinada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3633', 'spa', 'Pensar, suponer, imaginar; formarse una opinión o juicio subjetivo', 'Este verbo significa pensar, suponer o imaginar, es decir, formarse una opinión o estimación personal. Juan declara que el mundo entero no podría contener los libros sobre lo que hizo Jesús: «pienso» (Jn 21:25). Pablo menciona a quienes «suponen» erróneamente acerca de sus motivos (Fil 1:17). Santiago advierte al que «piensa» recibir del Señor mientras duda (Stg 1:7). El término indica un juicio subjetivo o estimación, no un conocimiento cierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3634', 'spa', 'Tal como, de qué clase, de qué tipo; pronombre relativo cualitativo que introduce comparaciones. Un pronombre relativo correlativo que caracteriza la ', 'Tal como, de qué clase, de qué tipo; pronombre relativo cualitativo que introduce comparaciones. Un pronombre relativo correlativo que caracteriza la cualidad o tipo de algo, respondiendo a la pregunta implícita ''¿de qué clase?'' En lugar de especificar cantidad o identidad, se enfoca en la naturaleza o el carácter de su referente. En el Nuevo Testamento aparece de manera memorable en descripciones escatológicas: ''tribulación cual no ha habido desde el principio'' (Mt 24:21; Mr 13:19), enfatizando la cualidad sin precedentes de la angustia de los últimos tiempos. Marcos lo usa vívidamente para describir la blancura sobrenatural de las vestiduras de Jesús en la Transfiguración: ''tal como ningún lavandero en la tierra podría blanquearlas'' (Mr 9:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3635', 'spa', 'Tardar, vacilar o ser lento para actuar; retraerse de hacer algo por renuencia o escrúpulo', 'Este verbo significa vacilar o demorar en hacer algo, frecuentemente por cautela, temor o renuencia. En Hechos 9:38, los discípulos de Jope enviaron un mensaje urgente a Pedro con la súplica: «No tardes en venir a nosotros» (ante la muerte de Tabita). La palabra lleva una carga emocional: temían que cualquier demora significara una oportunidad perdida, aunque Tabita ya había fallecido, pues albergaban la esperanza de una intervención divina. En el uso clásico incluye el sentido de retraerse por vergüenza, temor o escrúpulo. El imperativo negativo urgente subraya la esperanza desesperada de los discípulos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3636', 'spa', 'Perezoso, negligente, remiso; reacio a actuar o cumplir con el deber', 'Este adjetivo describe a quien es perezoso, negligente o reacio a actuar. Jesús condena al «siervo malo y perezoso» que enterró su talento (Mt 25:26). Pablo exhorta: «No seáis perezosos en el celo» (Ro 12:11). A los filipenses les indica que repetir las mismas instrucciones no le resulta «molesto» (Fil 3:1). El término abarca desde la pereza moral hasta la simple desgana práctica. El griego ὀκνηρός, derivado de ὄκνος (vacilación, retraimiento), cubre tanto la indolencia como la reluctancia ante la responsabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3637', 'spa', 'De ocho días de edad; que tiene ocho días desde el nacimiento', 'Este adjetivo describe a alguien o algo que tiene ocho días de edad. En Filipenses 3:5, Pablo enumera sus credenciales judías: «circuncidado al octavo día», es decir, cuando tenía ocho días de nacido, en obediencia precisa a la Ley. El término enfatiza no solo el momento sino la exactitud: Pablo no era un converso gentil que adoptó prácticas judías después, sino que fue incluido en el pacto desde su infancia. La formación compuesta (ocho + día) crea un adjetivo temporal preciso que se encuentra en contextos legales judíos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3638', 'spa', 'Ocho — el numeral cardinal 8, usado en expresiones temporales (días, años, personas). El numeral indeclinable ὀκτώ simplemente significa ''ocho.'' Sus d', 'Ocho — el numeral cardinal 8, usado en expresiones temporales (días, años, personas). El numeral indeclinable ὀκτώ simplemente significa ''ocho.'' Sus diez apariciones en el NT se concentran en frases temporales: Jesús fue circuncidado ''cuando se cumplieron ocho días'' (Lc 2:21), la Transfiguración ocurrió ''como ocho días después de estas palabras'' (Lc 9:28), y una mujer estuvo atada por enfermedad ''dieciocho años'' (literalmente ''diez y ocho,'' Lc 13:11, 16). El numeral también cuenta personas — ''ocho almas'' salvadas a través del agua en el arca de Noé (1 Pe 3:20; 2 Pe 2:5) y los dieciocho que murieron por la torre de Siloé (Lc 13:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3639', 'spa', 'Destruccion, ruina; devastacion total como juicio divino o perdida catastrofica.', 'Sustantivo de gran peso que designa ruina y devastacion, usado en el Nuevo Testamento exclusivamente para consecuencias catastroficas, ya sean impuestas por Dios o autoinfligidas. Pablo entrega al ofensor corintio a Satanas ''para destruccion de la carne'' (1 Corintios 5:5), mientras que 1 Tesalonicenses 5:3 advierte de una destruccion repentina sobre quienes dicen ''paz y seguridad''. El uso mas contundente aparece en 2 Tesalonicenses 1:9, donde ''destruccion eterna'' describe la separacion de la presencia de Dios. En 1 Timoteo 6:9, los deseos insensatos hunden a las personas en ruina y perdicion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3640', 'spa', 'De poca fe; que tiene confianza insuficiente o vacilante en el poder y la provisión de Dios', 'Adjetivo compuesto distintivamente mateano (ὀλίγος + πίστις) que Jesús emplea como reproche afectuoso pero incisivo hacia sus propios discípulos. Aparece en contextos de ansiedad material (''¿Por qué os preocupáis por el vestido?'', Matt 6:30), temor físico (''¿Por qué teméis?'', Matt 8:26), falta de valor (Pedro hundiéndose, Matt 14:31) y torpeza espiritual (la discusión sobre la levadura, Matt 16:8). La palabra no niega la fe por completo, sino que diagnostica su insuficiencia. El alemán ''Kleingläubiger'' captura hermosamente el compuesto: ''pequeño creyente.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3641', 'spa', 'Poco, escaso, pequeno en cantidad o numero; raramente usado adverbialmente como ''apenas'' o ''con dificultad''', 'Poco, escaso, pequeno en cantidad o numero; raramente usado adverbialmente como ''apenas'' o ''con dificultad''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3642', 'spa', 'Pusilánime, desanimado o de poco ánimo; aquellos cuyo espíritu es débil o desfallece', 'Este adjetivo describe a personas pusilánimes, desalentadas o faltas de valor; literalmente, de «alma pequeña» (ὀλίγος + ψυχή). En 1 Tesalonicenses 5:14, Pablo exhorta: «Animad a los de poco ánimo, sostened a los débiles, sed pacientes con todos». El contexto distingue distintos grupos que necesitan atención pastoral: los indisciplinados, los pusilánimes y los débiles. Se trata de creyentes cuyo ánimo o espíritu flaquea bajo la presión o la dificultad. La respuesta pastoral apropiada no es la reprensión sino el aliento, fortaleciendo a quienes vacilan en su determinación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3643', 'spa', 'Menospreciar, tener en poco o tratar como insignificante; despreciar o dar poca importancia a algo', 'Este verbo significa estimar algo ligeramente, considerarlo insignificante o darle poca importancia. En Hebreos 12:5, el autor cita Proverbios: «Hijo mío, no menosprecies la disciplina del Señor». La palabra implica una actitud desdeñosa: tratar la corrección de Dios como algo trivial o sin importancia, en lugar de reconocer su propósito redentor. El error opuesto (del que también se advierte en el mismo versículo) es desfallecer bajo la disciplina. La respuesta correcta requiere tomar en serio la corrección divina sin caer en la desesperación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3644', 'spa', 'Destructor; agente de destrucción, ruina o muerte, especialmente como ejecutor del juicio divino', 'Este sustantivo identifica a un agente de destrucción, alguien que destruye o arruina. En 1 Corintios 10:10, Pablo advierte a los corintios recordando los fracasos de Israel en el desierto: «algunos murmuraron y fueron destruidos por el Destructor». La referencia apunta al ángel de la muerte que ejecutó el juicio sobre el Israel rebelde (Números 16-17). El término aparece en contextos de juicio divino en la Septuaginta, designando a un agente destructor, ya sea un ejecutor angélico o la destrucción personificada. La advertencia de Pablo es clara: el mismo Destructor que juzgó a Israel puede juzgar a la iglesia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3645', 'spa', 'Que destruye o trae destrucción; el destructor, particularmente como agente del juicio divino', 'Este participio describe a alguien o algo que destruye o trae destrucción. En Hebreos 11:28, se refiere al ángel destructor de la Pascua: «Por la fe celebró la Pascua y roció la sangre, para que el Destructor de los primogénitos no los tocara». La referencia remite a Éxodo 12, donde la última plaga hirió a los primogénitos de Egipto pero pasó de largo en los hogares israelitas marcados con sangre de cordero. El participio personaliza la fuerza destructora como un agente activo que ejecuta el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3646', 'spa', 'Holocausto; sacrificio completamente consumido por el fuego como ofrenda a Dios', 'El holocausto es un sacrificio que se consume íntegramente por el fuego sobre el altar, ofrecido a Dios como acto de adoración y expiación. Jesús cita la Escritura: la obediencia y el amor importan más que los «holocaustos» (Mr 12:33). Hebreos recoge el Salmo 40: Dios no se complace en «holocaustos ni ofrendas por el pecado» (He 10:6, 8). El término representa todo el sistema sacrificial que el sacrificio único y definitivo de Cristo vino a reemplazar. El griego ὁλοκαύτωμα significa literalmente «completamente quemado».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3647', 'spa', 'Integridad completa, sanidad perfecta o plenitud total del cuerpo en todas sus partes', 'Este sustantivo denota integridad o plenitud completa, particularmente la sanidad total del cuerpo con todas sus partes funcionando correctamente. En Hechos 3:16, Pedro explica la sanación del mendigo cojo: «la fe en su nombre ha dado a este hombre la perfecta salud que ustedes ven». La palabra enfatiza una restauración total, no una mejoría parcial sino una plenitud completa. En el uso clásico incluye integridad física y buen funcionamiento de los sentidos. Pedro atribuye esta sanación integral a la fe en el nombre de Jesús, demostrando el poder del Cristo resucitado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3649', 'spa', 'Dar alaridos, lamentarse a gritos; proferir gemidos fuertes y lastimeros de dolor o duelo', 'Este verbo significa clamar con lamentos fuertes, a menudo ritualizados. En el griego clásico designaba típicamente los gritos de las mujeres dirigidos a los dioses en adoración, júbilo o lamentación. En Santiago 5:1, adquiere un tono ominoso: «¡Vamos ahora, ricos! Lloren y den alaridos por las miserias que les sobrevendrán». El verbo sugiere no lágrimas silenciosas sino un clamor fuerte y angustiado, apropiado para el juicio inminente que Santiago describe. La orden es irónica: comiencen su luto ahora, porque la catástrofe se acerca. La intensidad de la palabra capta la severidad del juicio que aguarda a quienes oprimen a los justos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3650', 'spa', 'Entero, todo, completo; denota totalidad o extensión plena, ocasionalmente usado como adverbio: «completamente»', 'ὅλος es el adjetivo griego para «entero» o «todo», y subraya que nada dentro del ámbito de referencia queda excluido. Cuando Jesús sana en sábado y pregunta si hacer a un hombre ὅλος sano lo justifica (Jn 7:23), la palabra conlleva tanto totalidad cuantitativa como plenitud cualitativa. Modifica ciudades («toda la ciudad», Mt 8:34), cuerpos («todo tu cuerpo», Mt 5:29-30) y períodos temporales («un año entero», Hch 11:26). El español «todo/toda» y «entero» reflejan uniformemente el significado nuclear de totalidad indivisa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3651', 'spa', 'Completamente, enteramente, en todas sus partes; de manera íntegra y total de principio a fin', 'Este adjetivo significa completamente entero, sin que falte parte alguna. En 1 Tesalonicenses 5:23, Pablo ora: «Que el mismo Dios de paz os santifique por completo, y que todo vuestro ser —espíritu, alma y cuerpo— sea guardado irreprensible». La palabra enfatiza la totalidad: una santificación integral que abarca cada dimensión de la persona. La oración no pide una santidad parcial sino una transformación completa que abarque todos los aspectos del ser. Las traducciones en diversas lenguas mantienen este sentido de plenitud integral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3652', 'spa', 'Olimpas, creyente cristiano en Roma saludado por Pablo; probablemente forma abreviada de Olimpiodoro', 'Olimpas es un nombre propio, probablemente una forma abreviada de Olimpiodoro o un compuesto similar. En Romanos 16:15, Pablo envía saludos: «Saludad a Filólogo y a Julia, a Nereo y a su hermana, a Olimpas y a todos los santos que están con ellos.» Esta breve mención sitúa a Olimpas entre los creyentes de Roma, posiblemente como parte de una iglesia doméstica. El nombre deriva del monte Olimpo, morada de los dioses en la mitología griega, aunque para el siglo I era simplemente un nombre común sin connotación religiosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3653', 'spa', 'Higos verdes o inmaduros; frutos tardíos que caen antes de madurar, o higos tempranos desprendidos prematuramente', 'Este sustantivo designa los higos verdes o inmaduros, ya sea los frutos tardíos del verano que no llegan a madurar o los higos tempranos que el viento arranca antes de su sazón. En Apocalipsis 6:13, aparece dentro de la imaginería de catástrofe cósmica: «las estrellas del cielo cayeron sobre la tierra, como la higuera deja caer sus higos verdes cuando es sacudida por un fuerte viento.» La comparación es vívida: así como un viento violento despoja a la higuera de su fruto inmaduro, la conmoción cósmica arranca las estrellas del cielo. La imagen transmite un colapso total e imparable del orden creado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3654', 'spa', 'Del todo, en absoluto, realmente; adverbio que intensifica o generaliza una afirmacion.', 'Adverbio derivado de ὅλος (entero, total) que refuerza afirmaciones en distintas direcciones segun el contexto. En Mateo 5:34, Jesus dice ''no jureis en absoluto'', usandolo para establecer una prohibicion total. Pablo lo emplea en 1 Corintios 5:1 para expresar indignacion: ''de hecho se oye'', y en 1 Corintios 6:7 para declarar que los pleitos entre creyentes son ''del todo una derrota''. La pregunta retorica de 1 Corintios 15:29 lo usa para reforzar el argumento logico: ''si los muertos no resucitan en absoluto''. Transmite totalidad o completitud enfatica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3655', 'spa', 'Aguacero, tormenta de lluvia; chaparrón repentino y a menudo violento, frecuentemente asociado con intervención divina', 'Este sustantivo designa un aguacero o tormenta de lluvia intensa, distinguiéndose de la lluvia ordinaria (ὑετός) por su intensidad y carácter repentino. En Homero y los autores clásicos, con frecuencia denota una tormenta enviada por Zeus, violenta e incluso destructiva. La palabra también puede tener fuerza metafórica, describiendo la embestida de una batalla o calamidad. En Lucas 12:54, Jesús la emplea en un proverbio meteorológico: cuando una nube se levanta por el poniente, viene el ὄμβρος (el aguacero). No se trata de una llovizna suave, sino de la lluvia que llega con fuerza y exige atención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3656', 'spa', 'Conversar, hablar con alguien; mantener un diálogo prolongado e íntimo, distinto del discurso formal o público.', 'Describe una conversación sostenida y personal, no un discurso público ni formal. En el camino a Emaús, los dos discípulos iban «conversando» sobre todo lo sucedido cuando Jesús se les acercó (Lc 24:14-15), un intercambio íntimo y reflexivo. En Hechos 20:11, Pablo conversó con los creyentes de Troas hasta el amanecer tras la caída de Eutico. En Hechos 24:26, Félix mandaba llamar repetidamente a Pablo para «conversar» con él, esperando un soborno. El vocablo implica consistentemente un diálogo prolongado y recíproco, un ir y venir de palabras entre interlocutores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3657', 'spa', 'Compañía, trato o asociación con otros; convivencia frecuente que moldea el carácter', 'Este sustantivo denota la compañía, el trato o la interacción frecuente con otros: «las amistades que uno frecuenta.» En 1 Corintios 15:33, Pablo cita un proverbio griego: «Las malas compañías corrompen las buenas costumbres.» La palabra subraya una asociación sostenida, no un contacto pasajero: el círculo social que moldea el carácter mediante su influencia continua. La advertencia es práctica: la formación moral ocurre a través de las relaciones, y las asociaciones corruptoras erosionan la virtud. La forma plural puede significar «compañeros» o «amistades», destacando las redes sociales que nos forman.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3658', 'spa', 'multitud, tropel, asamblea (cualquier grupo reunido); la masa del pueblo, especialmente frente a los líderes', 'El ὅμιλος designa cualquier multitud reunida, ya sea para un banquete, un espectáculo o una batalla. Homero lo emplea con frecuencia para referirse a tropeles de guerreros o al pueblo llano en contraposición a los jefes. Puede designar la masa de tropas irregulares (armamento ligero) frente a los hoplitas, o a la turba frente a los instruidos. Heráclito menosprecia a la multitud como mal maestro. La palabra también puede aplicarse a agrupaciones de objetos inanimados, y enfatiza lo colectivo, a menudo con un matiz de la masa indiferenciada frente a los pocos distinguidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3660', 'spa', 'Jurar, hacer un juramento; obligarse solemnemente invocando una autoridad superior o un objeto sagrado.', 'Jurar, hacer un juramento; obligarse solemnemente invocando una autoridad superior o un objeto sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3661', 'spa', 'Unánimemente, de común acuerdo — adverbio que describe armonía colectiva de propósito, especialmente en la vida de la iglesia primitiva. El adverbio ὁ', 'Unánimemente, de común acuerdo — adverbio que describe armonía colectiva de propósito, especialmente en la vida de la iglesia primitiva. El adverbio ὁμοθυμαδόν describe a un grupo que actúa o siente ''con un mismo sentir'' o ''de común acuerdo.'' Es prácticamente una palabra distintiva de Hechos, donde Lucas lo utiliza para retratar la extraordinaria unidad de la iglesia primitiva: los discípulos oran juntos de común acuerdo (Hch 1:14), se reúnen diariamente en el templo (Hch 2:46), elevan sus voces en oración unificada (Hch 4:24) y se congregan en el Pórtico de Salomón (Hch 5:12). La palabra también capta la unanimidad hostil — una multitud lanzándose con un mismo impulso contra Esteban (Hch 7:57) o contra Pablo en Tesalónica. Su única aparición paulina es Ro 15:6, orando para que los creyentes puedan ''con un mismo sentir y una misma boca glorificar a Dios.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3662', 'spa', 'Ser semejante o parecido a algo; asemejarse o tener similitud con otro', 'Este verbo significa ser semejante, parecerse o tener similitud con otra cosa. En Marcos 14:70, los presentes interpelan a Pedro durante el juicio de Jesús: «Ciertamente tú eres uno de ellos, porque eres galileo y tu habla es semejante.» El verbo indica que el acento o dialecto de Pedro coincidía con el de los galileos, delatando su origen regional a pesar de sus negaciones. En otros contextos la palabra también puede significar «comparar», pero aquí se trata del parecido o semejanza que revela la identidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3664', 'spa', 'Semejante, similar, parecido — expresa semejanza o analogia, especialmente en parabolas y visiones', 'Semejante, similar, parecido — expresa semejanza o analogia, especialmente en parabolas y visiones');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3666', 'spa', 'Comparar, asemejar o hacer semejante; en voz pasiva, ser comparado o llegar a ser como algo. En el corazón de las introducciones parabólicas de Jesús ', 'Comparar, asemejar o hacer semejante; en voz pasiva, ser comparado o llegar a ser como algo. En el corazón de las introducciones parabólicas de Jesús se encuentra este verbo de comparación. ''El reino de los cielos es semejante a...'' (Mt 13:24; 18:23; 22:2) emplea la voz pasiva, mientras que ''¿A qué compararé esta generación?'' (Mt 11:16; Lc 7:31) usa la voz activa retóricamente. Más allá de la mera ilustración, la palabra puede denotar semejanza real: Cristo ''fue hecho semejante'' a sus hermanos (He 2:17), y Pablo advierte a los creyentes que no ''se asemejen'' a las naciones (Mt 6:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3667', 'spa', 'Semejanza, forma, apariencia; representación visible o similitud de algo', 'Sustantivo que designa la forma, figura o parecido visible que una cosa guarda con otra. Pablo lo emplea con notable precisión teológica: la humanidad cayó ''a la semejanza de la transgresión de Adán'' (Rom 5:14), Cristo fue enviado ''en semejanza de carne de pecado'' (Rom 8:3) y tomó ''la semejanza de los hombres'' (Fil 2:7). El vocablo implica cuidadosamente un parecido genuino sin afirmar identidad completa, distinción crucial en la formulación cristológica. Tanto el español ''semejanza'' como el alemán ''Gleichnis'' capturan este matiz de ''semejanza sin identidad.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3668', 'spa', 'asimismo, de la misma manera — adverbio que establece un paralelo entre acciones, situaciones u órdenes', 'asimismo, de la misma manera — adverbio que establece un paralelo entre acciones, situaciones u órdenes');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3669', 'spa', 'Semejanza, parecido o similitud; el estado de ser hecho a imagen de algo o alguien', 'Este sustantivo designa la semejanza o el parecido, especialmente el estado de ser hecho similar a algo. En Santiago 3:9, aparece dentro de una denuncia ética: ''Con la lengua bendecimos a nuestro Señor y Padre, y con ella maldecimos a personas hechas a semejanza de Dios.'' La expresión evoca Génesis 1:26-27: la humanidad porta la imagen y semejanza divina. El argumento de Santiago es contundente: maldecir a los seres humanos es indirectamente ofender a Dios, cuya semejanza llevan. El término subraya la similitud que vincula a la humanidad con lo divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3670', 'spa', 'Confesar, reconocer, profesar; concordar abiertamente, declarar públicamente o prometer formalmente.', 'Confesar, reconocer, profesar; concordar abiertamente, declarar públicamente o prometer formalmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3671', 'spa', 'Confesión, profesión; declaración pública de fe o lealtad', 'Derivado de ὁμολογέω (''decir lo mismo, concordar''), este sustantivo designa una declaración pública y vinculante, ya sea de fe, lealtad o compromiso. En Hebreos se convierte casi en un término técnico para la profesión cristiana de fe: Jesús es ''el apóstol y sumo sacerdote de nuestra confesión'' (Heb 3:1) y los creyentes deben ''mantener firme la confesión'' (Heb 4:14). Pablo recuerda a Timoteo ''la buena confesión'' que hizo ante muchos testigos (1 Tim 6:12), en paralelo con el testimonio de Cristo ante Pilato. La coherencia del término en distintas lenguas —''confesión'' en español y francés, ''Bekenntnis'' en alemán— refleja su estabilidad como vocablo de declaración pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3672', 'spa', 'Confesadamente, reconocidamente o por acuerdo común; algo reconocido y aceptado por todos', 'Este adverbio significa ''confesadamente'' o ''reconocidamente'', es decir, por consenso común o acuerdo universal. En 1 Timoteo 3:16, Pablo lo emplea para introducir un himno credal: ''Grande es, sin duda alguna, el misterio de la piedad.'' La palabra señala que lo que sigue es universalmente reconocido entre los creyentes, no doctrina disputada sino verdad fundacional. En el uso clásico también puede significar ''de manera conforme a'', pero aquí enfatiza la confesión común o la verdad aceptada por todos. El himno cristológico que sigue es lo que la iglesia confesadamente cree.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3673', 'spa', 'Del mismo oficio o profesión; un compañero de trabajo artesanal que comparte la misma ocupación', 'Este adjetivo describe a alguien que ejerce el mismo oficio o profesión, un compañero artesano. En Hechos 18:3, explica por qué Pablo se alojó con Aquila y Priscila en Corinto: ''porque era del mismo oficio, se quedó con ellos y trabajaban juntos, pues eran fabricantes de tiendas de oficio.'' La ocupación compartida creó una asociación natural: colaboración económica y apoyo mutuo en una ciudad nueva. El término destaca la afinidad profesional que facilitó tanto la cooperación práctica como la asociación en el ministerio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3674', 'spa', 'Juntos, en el mismo lugar; al mismo tiempo o en compañía unos de otros.', 'Adverbio que expresa estar juntos, ya sea en sentido espacial (mismo lugar), temporal (mismo momento) o relacional (en compañía). El Evangelio de Juan lo emplea para los discípulos reunidos juntos (Jn 21:2) y para dos discípulos corriendo juntos hacia el sepulcro (Jn 20:4). En Juan 4:36, el sembrador y el segador se regocijan «juntos», eliminando la distancia temporal habitual entre la siembra y la cosecha. Hechos 2:1 sitúa a todos los creyentes «juntos en un mismo lugar» en Pentecostés, combinando la cercanía espacial con la comunión fraternal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3675', 'spa', 'Unánime, de un mismo sentir o concordes en pensamiento; que comparten la misma disposición o actitud', 'Este adjetivo describe a personas que son unánimes o concordes en pensamiento, literalmente ''de la misma mente'' (ὁμός + φρήν). En 1 Pedro 3:8, encabeza una lista de virtudes relacionales: ''Finalmente, sed todos de un mismo sentir, compasivos, fraternales, misericordiosos y humildes.'' El término enfatiza la concordancia intelectual y emocional: perspectiva compartida y entendimiento mutuo dentro de la comunidad cristiana. Es armonía relacional enraizada en convicciones y afectos comunes, esencial para la unidad de la iglesia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3676', 'spa', 'sin embargo, no obstante, con todo; conjunción que introduce una cláusula concesiva o limitante', 'Esta conjunción introduce una cláusula concesiva o de contraste: «sin embargo», «no obstante», «con todo». Muchos creyeron en Jesús pero no lo confesaban por temor; Juan añade: «Con todo, aun muchos de los gobernantes creyeron» (Juan 12:42). Pablo señala que los instrumentos inanimados necesitan distinción de notas, «pues de otro modo, ¿cómo se sabrá...?» (1 Co 14:7). A los gálatas les dice que un pacto humano, una vez ratificado, no puede anularse: «sin embargo» (Gá 3:15). La palabra marca un contraste o matiz que limita lo anterior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3677', 'spa', 'Sueño; visión recibida durante el dormir, especialmente como comunicación divina', 'La palabra griega estándar para un sueño experimentado durante el dormir, distinto de las visiones en estado de vigilia. En el NT aparece exclusivamente en la narrativa de la infancia según Mateo, donde los sueños sirven como canal elegido por Dios para guiar a José y a los Magos a través de las circunstancias peligrosas que rodearon el nacimiento de Jesús. Un ángel se aparece a José ''en sueños'' cuatro veces (Matt 1:20; 2:13, 19, 22), y los Magos son advertidos ''en sueños'' de no volver a Herodes (Matt 2:12). La concentración en un solo bloque narrativo subraya el retrato teológico mateano de la providencia divina dirigiendo los eventos mediante revelación nocturna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3678', 'spa', 'Borriquillo o asno joven; un pollino, a menudo en sentido diminutivo para un animal pequeño o joven', 'Este sustantivo diminutivo se refiere a un asno joven o pequeño, un pollino. En Juan 12:14, describe la montura de Jesús para la entrada triunfal: ''Jesús halló un asnillo y montó sobre él, como está escrito.'' El detalle cumple la profecía de Zacarías 9:9 acerca del rey que viene ''humilde y montado sobre un asno, sobre un pollino hijo de asna.'' La forma diminutiva puede enfatizar la pequeñez o juventud del animal, subrayando la humildad de la entrada real de Jesús: no un caballo de guerra, sino una humilde bestia de carga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3679', 'spa', 'Injuriar, reprochar o insultar; reprender con severidad; reprochar en el sentido de recriminar a quien da.', 'Verbo que expresa un ataque verbal que va desde insultos hostiles hasta censura con autoridad. Cuando los perseguidores injurian a los creyentes o se burlan de Cristo en la cruz (Mt 5:11; Mt 27:44; Mc 15:32), la palabra conlleva el aguijón del desprecio abusivo. Cuando Jesús mismo ''reprocha'' a las ciudades que no se arrepintieron (Mt 11:20) o reprende a sus discípulos por su incredulidad (Mc 16:14), el mismo verbo se desplaza hacia la reprensión con autoridad. Santiago 1:5 presenta una notable inversión teológica: Dios da sabiduría generosamente ''sin reprochar'', el único contexto donde el vocablo aparece en negación, asegurando a los creyentes que la generosidad divina no viene acompañada de recriminación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3680', 'spa', 'Oprobio, afrenta, vituperio; vergüenza o insulto soportado por causa de la fe o la identidad.', 'Sustantivo que denota oprobio, afrenta o vituperio: la experiencia de ser públicamente avergonzado o insultado. En el Nuevo Testamento aparece de forma constante en contextos de sufrimiento por la fe. Romanos 15:3 cita el Salmo 69:9, aplicando a Cristo mismo los oprobios dirigidos contra Dios. Hebreos desarrolla este tema con mayor riqueza: los creyentes soportaron públicamente vituperios y tribulaciones (10:33), Moisés escogió «el oprobio de Cristo» por encima de los tesoros de Egipto (11:26), y se exhorta a la comunidad a salir fuera del campamento llevando su afrenta (13:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3681', 'spa', 'Reproche, deshonra o vergüenza; condición de humillación o estigma social, especialmente escarnio público', 'Este sustantivo designa el reproche, la deshonra o aquello que acarrea vergüenza, particularmente el escarnio público o la humillación social. En Lucas 1:25, Elisabet responde a su embarazo: «Así ha obrado el Señor conmigo en los días en que se dignó quitar mi afrenta entre los hombres.» En aquella cultura, la esterilidad se percibía como señal de desfavor divino, lo cual generaba un estigma social profundo. El «reproche» de Elisabet era la vergüenza y la compasión murmurada que soportó durante años. El don de un hijo por parte de Dios eliminó esa deshonra, reivindicándola ante su comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3685', 'spa', 'Obtener beneficio o provecho de algo o alguien; sacar ventaja o ser ayudado por otro', 'Este verbo significa beneficiarse, sacar provecho u obtener ventaja de algo o de alguien. En Filemón 20, Pablo escribe: «Sí, hermano, que yo tenga este beneficio de ti en el Señor.» El verbo está emparentado con el nombre Onésimo (que significa «útil» o «provechoso»), lo cual genera un juego de palabras deliberado en la carta de Pablo. Pablo le pide a Filemón que le conceda gozo y beneficio al recibir de vuelta a Onésimo con gracia. El término combina beneficio material y relacional: Pablo busca tanto ayuda concreta como armonía en la relación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3686', 'spa', 'Nombre, título o reputación; designa personas, lugares y autoridad divina («en el nombre de»)', 'En el griego bíblico, ὄνομα abarca mucho más que una etiqueta identificativa. Denota el nombre propio, el título, la fama y la autoridad de una persona. Cuando la Escritura habla de actuar o creer «en el nombre de» Jesús, la palabra porta el peso pleno de la identidad y el poder de esa persona. En pasajes como Mt 1:21 («le pondrás por nombre Jesús») y Hch 4:12 («no hay otro nombre bajo el cielo»), el término se adentra en territorio teológico, significando reputación, carácter y autoridad salvífica. El español «nombre» capta fielmente este núcleo semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3687', 'spa', 'Nombrar, llamar por nombre -- otorgar un nombre, designar o ser conocido/identificado por un nombre o titulo. El verbo onomazo (ὀνομάζω) abarca tanto ', 'Nombrar, llamar por nombre -- otorgar un nombre, designar o ser conocido/identificado por un nombre o titulo. El verbo onomazo (ὀνομάζω) abarca tanto el acto de nombrar activamente como el de ser nombrado pasivamente. Jesus ''nombro'' activamente a los doce apostoles (Marcos 3:14 v.l.; Lucas 6:13-14), estableciendo su identidad y mision. En voz pasiva, describe titulos y reputaciones que trascienden la era presente: Cristo fue exaltado sobre todo nombre ''que se nombra'' (Efesios 1:21), y toda familia en el cielo y la tierra ''es nombrada'' por el Padre (Efesios 3:15). Pablo evita edificar donde Cristo ''ha sido nombrado'' (Romanos 15:20), y ciertos pecados ''ni siquiera deben nombrarse'' entre los creyentes (Efesios 5:3; 1 Corintios 5:11). El verbo tambien aparece en formulas de exorcismo: judios itinerantes ''nombrando'' el nombre de Jesus (Hechos 19:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3688', 'spa', 'Asno, burro; animal de carga común en el antiguo Cercano Oriente, protagonista de la entrada triunfal de Jesús.', 'El asno o burro común, uno de los animales de trabajo más importantes del mundo bíblico. Tres de sus cinco apariciones en el Nuevo Testamento se relacionan con la entrada triunfal de Jesús en Jerusalén, cumpliendo Zacarías 9:9: «montado sobre un asno» (Mt 21:2, 5, 7). Juan 12:15 se hace eco de la misma profecía. Lucas 13:15 lo emplea en una disputa sabática: hasta un asno se desata y se lleva al agua en sábado. La distinción en español entre «asno» (macho) y «asna» (hembra) refleja la mención en Mateo tanto de una asna como de su pollino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3689', 'spa', 'Verdaderamente, realmente -- adverbio que afirma la realidad genuina, ''en verdad'', ''ciertamente''. El adverbio ontos (ὄντως), derivado del participio p', 'Verdaderamente, realmente -- adverbio que afirma la realidad genuina, ''en verdad'', ''ciertamente''. El adverbio ontos (ὄντως), derivado del participio presente de eimi (''ser''), asevera que algo es genuinamente el caso y no meramente aparente. La gente sostenia que Juan ''verdaderamente era'' profeta (Marcos 11:32). El centurion al pie de la cruz declaro: ''Ciertamente este hombre era justo'' (Lucas 23:47). Los discipulos confirmaron: ''El Senor verdaderamente ha resucitado'' (Lucas 24:34). Pablo distingue a las viudas ''verdaderamente'' viudas de aquellas con apoyo familiar (1 Timoteo 5:3,5,16) y exhorta a Timoteo a asirse de ''lo que es verdaderamente vida'' (1 Timoteo 6:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3690', 'spa', 'Vino agrio, vinagre; bebida ácida barata usada comúnmente por los soldados romanos', 'Un vino ácido y áspero —no vinagre destilado, sino el ''vino ordinario'' barato (posca) que los soldados romanos llevaban como bebida cotidiana. Las seis apariciones en el NT se encuentran en los relatos de la Pasión, donde se ofrece a Jesús en la cruz. El significado del gesto es debatido: en algunos relatos parece burlón (Lucas 23:36), mientras que en Juan 19:29 podría ser un acto de tosca misericordia para humedecer los labios del moribundo. El detalle está atestiguado en los cuatro Evangelios, convirtiéndolo en uno de los elementos más ampliamente corroborados de la crucifixión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3691', 'spa', 'Agudo, afilado; veloz, rápido — del filo cortante de una hoja o de pies que se mueven con rapidez.', 'El adjetivo ὀξύς aparece ocho veces en el Nuevo Testamento, casi en su totalidad en las visiones de Apocalipsis con hoces afiladas y espadas de doble filo. En siete de ellas describe el filo cortante de un arma o herramienta de siega: la espada aguda de dos filos que sale de la boca de Cristo (Ap 1:16; 2:12) y la hoz afilada de la cosecha escatológica (Ap 14:14, 17, 18). Una única aparición en Romanos 3:15, citando Isaías 59:7, gira hacia un sentido completamente distinto: ''veloces son sus pies para derramar sangre'', donde ὀξύς describe movimiento rápido en vez del filo de una hoja.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3693', 'spa', 'Detrás, por detrás, a la espalda; adverbio/preposición espacial que indica posición o aproximación desde la parte posterior', 'ὄπισθεν indica posición o movimiento desde atrás, y casi todas sus apariciones en el NT involucran a alguien que se acerca a Jesús por la espalda. La mujer con flujo de sangre toca el borde de su manto ''por detrás'' en los tres relatos sinópticos (Mt 9:20; Mr 5:27; Lc 8:44), detalle que sugiere su reticencia y vergüenza ritual. En Mt 15:23 la mujer cananea clama ''detrás'' de Jesús y los discípulos. En Lc 23:26 Simón de Cirene carga la cruz ''detrás'' de Jesús. La palabra aporta viveza narrativa al señalar la dirección desde la que alguien se aproxima.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3694', 'spa', 'después, detrás, atrás — adverbio espacial o temporal que indica seguir, estar detrás o volverse hacia atrás', 'después, detrás, atrás — adverbio espacial o temporal que indica seguir, estar detrás o volverse hacia atrás');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3695', 'spa', 'Armarse o equiparse, especialmente con armas o armadura; prepararse para la batalla o el conflicto', 'Este verbo significa armarse o equiparse, particularmente con armas o armadura para el combate. En 1 Pedro 4:1 se emplea de manera metafórica: «Puesto que Cristo padeció en la carne, armaos también vosotros con la misma disposición de ánimo.» Pedro transforma la imaginería militar en exhortación espiritual: así como los soldados se equipan con armas, los creyentes deben equiparse con la mentalidad de Cristo respecto al sufrimiento. La metáfora implica una preparación deliberada y una disposición activa ante las dificultades, no resignación pasiva, sino un armamento mental y espiritual consciente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3696', 'spa', 'Arma, instrumento, herramienta; implementos de guerra o equipamiento moral y espiritual', 'Sustantivo versátil cuyo rango clásico abarca aparejos de barco, herramientas de herrero y armas militares. En el NT aparece tanto en sentido literal como figurado. Juan 18:3 describe al grupo que arrestó a Jesús llegando con «armas», pero Pablo transforma la palabra en metáfora del equipamiento moral y espiritual del creyente: los fieles no deben ofrecer sus miembros como «instrumentos de injusticia» sino como «instrumentos de justicia» (Rom 6:13), deben vestirse con «las armas de la luz» (Rom 13:12) y empuñar «las armas de la justicia» (2 Cor 6:7). La distinción en español entre «armas» e «instrumentos» refleja fielmente esta dualidad militar-utilitaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3697', 'spa', 'De qué clase, de qué tipo; pronombre relativo cualitativo que indica la naturaleza o el carácter de algo.', 'Pronombre relativo cualitativo que significa «de qué clase» o «de qué tipo», usado para caracterizar la naturaleza o cualidad de algo más que su identidad. En Hechos 26:29, Pablo desea que sus oyentes lleguen a ser «tal como yo soy» (ὁποῖος): la palabra se centra en la cualidad de su fe, no en mera semejanza. En 1 Corintios 3:13, el fuego revela «de qué clase» es la obra de cada uno. Gálatas 2:6 lo emplea de forma despectiva respecto a la condición anterior de los líderes de Jerusalén. El español «de qué clase» capta bien su fuerza interrogativo-cualitativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3698', 'spa', 'cuando, siempre que (adverbio relativo temporal, menos definido que ὅτε); con indicativo o subjuntivo', 'El adverbio temporal ὁπότε (épico ὁππότε, jónico ὁκότε) funciona de manera similar a ὅτε, pero con menor grado de definición. Con indicativo se refiere a ocasiones pasadas: «cuando ella estaba viva». Con subjuntivo, como ὁπόταν, indica ocasiones indefinidas o repetidas en tiempo presente o futuro. En símiles puede acompañar al presente: «como cuando un río se precipita hacia la llanura». Las variantes dialectales (ὁππόκα en dórico) testimonian el uso extendido de esta palabra a lo largo de las tradiciones literarias griegas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3699', 'spa', 'Donde, dondequiera — adverbio relativo de lugar que indica ubicación o destino', 'El adverbio relativo de lugar ὅπου significa «donde» o «dondequiera que», y se emplea para especificar una ubicación en relación con un antecedente o para introducir una condición espacial general. En los Evangelios aparece frecuentemente en la enseñanza de Jesús: el tesoro y el corazón (Mt 6:21), la reunión de las águilas (Mt 24:28) y «donde yo estoy, vosotros también estaréis» (Jn 14:3). Puede combinarse con ἄν o ἐάν para formar el indefinido «dondequiera que» (Mc 6:56; 14:9). Sus 84 apariciones abarcan contextos narrativos, discursivos y proféticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3700', 'spa', 'Ser visto o aparecer; hacerse visible o manifestarse, frecuentemente en sentido sobrenatural o revelatorio', 'Este verbo en voz pasiva significa ser visto, aparecer o hacerse visible, a menudo con connotaciones de revelación divina o manifestación sobrenatural. En Hechos 1:3 describe las apariciones de Jesús tras la resurrección: «A quienes también, después de haber padecido, se presentó vivo con muchas pruebas indubitables, apareciéndoseles durante cuarenta días.» El término subraya la visibilidad y tangibilidad: Jesús fue visto, probando así su resurrección corporal. La voz pasiva puede sugerir iniciativa divina: él se dejó ver, revelando su estado de resucitado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3701', 'spa', 'Vision sobrenatural; aparicion o revelacion visual procedente de Dios.', 'Se refiere a una revelacion visual de origen divino, algo que se ve y que transmite un mensaje de parte de Dios. Cuando Zacarias se demora en el templo y sale sin poder hablar, la gente comprende que ha tenido una vision (Lc 1:22). Las mujeres en la tumba vacia informan de una ''vision de angeles'' que declararon a Jesus vivo (Lc 24:23). Pablo relata ante Agripa que no fue ''desobediente a la vision celestial'' en el camino a Damasco (Hch 26:19), y en 2 Corintios 12:1 menciona ''visiones y revelaciones del Senor.'' Un unico sentido bien definido de percepcion sobrenatural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3702', 'spa', 'Asado, cocido a la brasa o al fuego; alimento preparado por calor directo en lugar de hervido', 'Este adjetivo describe alimento asado o cocido a la brasa, es decir, preparado sobre fuego directo en contraste con hervido u horneado. En Lucas 24:42, los discípulos le dan al Jesús resucitado algo de comer: «Entonces le dieron parte de un pez asado.» Este detalle subraya la naturaleza física y material de la resurrección: Jesús come comida real preparada de forma ordinaria. El pescado asado era un alimento común, y el hecho de que Jesús lo consumiera demuestra que no era un fantasma ni una visión, sino que poseía un cuerpo tangible y físico. El detalle cotidiano ancla el milagro extraordinario en la realidad material.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3703', 'spa', 'Fruto tardío de verano o cosecha; fruto maduro, especialmente la temporada en que el fruto madura y se recoge', 'Este sustantivo se refiere al final del verano, la temporada de cosecha de frutos, o al fruto maduro en sí, particularmente el período entre el verano y el otoño. En Apocalipsis 18:14 aparece en un lamento por la caída de Babilonia: «El fruto que satisfacía el anhelo de tu alma se fue de ti». El término probablemente designa frutos selectos o maduros, simbolizando lujo y extravagancia. La imagen es de abundancia codiciada que desaparece súbitamente: prosperidad material arrebatada en el juicio. Las asociaciones estacionales del vocablo (abundancia de cosecha) intensifican la tragedia de la pérdida repentina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3704', 'spa', 'Conjunción de propósito («para que, a fin de que») o de modo interrogativo («cómo, de qué manera»)', 'En el Nuevo Testamento se usa de forma abrumadoramente mayoritaria como conjunción de propósito con el significado de «para que» o «a fin de que», introduciendo la meta o el resultado buscado de una acción. En un puñado de pasajes conserva su fuerza interrogativa clásica, con el sentido de «cómo» o «de qué manera», como cuando los fariseos traman cómo atrapar a Jesús (Mt 22:15). La evidencia multilingüe confirma con claridad la división: el español «para que» cubre uniformemente el sentido de propósito, mientras que «cómo» recoge el interrogativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3705', 'spa', 'Una visión o manifestación sobrenatural concedida por Dios, frecuentemente durante la oración o un estado de éxtasis; también un espectáculo impactant', 'Una visión o manifestación sobrenatural concedida por Dios, frecuentemente durante la oración o un estado de éxtasis; también un espectáculo impactante que capta la atención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3706', 'spa', 'Vision, aspecto; el acto de ver o una percepcion sobrenatural; tambien apariencia exterior o semblante.', 'En el Nuevo Testamento este sustantivo abarca tanto el acto concreto de ver como la experiencia extraordinaria de una vision otorgada por Dios. En el sermon de Pentecostes, Pedro cita la promesa de Joel de que ''vuestros jovenes veran visiones'' (Hch 2:17), mientras que en Apocalipsis describe la apariencia exterior: ''semejante en aspecto al jaspe'' (Ap 4:3). La evidencia multilingue resalta esta bifurcacion: el pasaje de Hechos se traduce como ''visiones,'' pero los textos de Apocalipsis emplean ''en aspecto.'' La palabra tiende asi un puente entre la vista ordinaria y el encuentro revelatorio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3707', 'spa', 'Visible, que puede ser visto; perceptible a los ojos, no meramente intelectual o espiritual', 'Este adjetivo significa visible o perceptible a la vista, en contraposición a lo invisible o puramente conceptual. En Colosenses 1:16, Pablo describe la obra creadora de Cristo: «Porque en él fueron creadas todas las cosas, las que hay en los cielos y las que hay en la tierra, visibles e invisibles». El vocablo traza la distinción entre la creación física y material (las cosas visibles) y la realidad espiritual e inmaterial (tronos, dominios, principados). La soberanía de Cristo abarca ambos ámbitos: materia y espíritu, lo visto y lo no visto. El término enfatiza la realidad empírica y perceptible por los sentidos, en contraste con las realidades espirituales o intelectuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3708', 'spa', 'Ver, percibir visualmente; como interjec. ''!he aqui!''; en voz pasiva, aparecer, hacerse visible; por ext., percibir mentalmente.', 'Horao es el verbo griego fundamental de la vista, y en el Nuevo Testamento su alcance va mucho mas alla de la simple percepcion visual. Su participio aoristo idon (''habiendo visto'') impulsa relato tras relato: los magos ''vieron'' la estrella (Mt 2:10), Jesus ''vio'' las multitudes (Mt 5:1), Tomas finalmente ''vio'' al Senor resucitado (Jn 20:29). Su contribucion mas distintiva es la forma exclamativa idou (''!he aqui!''), que aparece mas de 250 veces como foco dramatico para anuncios angelicos, visiones profeticas e intervenciones divinas. La voz pasiva ophthe (''aparecio'') se convierte en el vocabulario estandar de la resurreccion y la teofania: Cristo ''aparecio'' a Pedro, a los doce, a quinientos (1 Co 15:5-8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3709', 'spa', 'Ira, enojo o indignación vehemente; tanto la furia judicial divina como la cólera pasional humana', 'Ira, enojo o indignación vehemente; tanto la furia judicial divina como la cólera pasional humana');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3710', 'spa', 'Enojarse, airarse o ser provocado a ira; usado en el NT exclusivamente en voz pasiva para el inicio o estado de enojo.', 'Ὀργίζω (de ὀργή, ira) significa provocar a ira en voz activa, pero las ocho apariciones neotestamentarias son todas pasivas: alguien se enoja o es movido a ira. El rango se extiende desde la intensa emoción del propio Jesús (la variante textual en Mc 1:41), pasando por la furia de un rey desairado (Mt 22:7) y un anfitrión ofendido (Lc 14:21), hasta el consejo mesurado de Pablo en Efesios 4:26, que toma prestado del Salmo 4: ''Enojaos, pero no pequéis''. El español ''enojarse'' capta bien la cualidad reflexiva y experiencial de esta ira en voz pasiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3711', 'spa', 'Irascible, propenso a la ira; inclinado a arrebatos de cólera o que se enoja con facilidad', 'Este adjetivo describe a alguien irascible o colérico, propenso a la ira y dado a estallidos de genio. En Tito 1:7, Pablo enumera las descalificaciones para los ancianos: «Porque es necesario que el obispo sea irreprensible, como administrador de Dios; no soberbio, no iracundo». El término no indica enojo ocasional sino una tendencia temperamental: alguien cuya ira se enciende fácil y frecuentemente. Tal volatilidad descalifica a una persona para pastorear al pueblo de Dios, que necesita un liderazgo paciente y mesurado, no reacciones explosivas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3713', 'spa', 'desear, anhelar, aspirar a, extenderse hacia una meta noble o indigna', 'Este verbo significa extenderse hacia algo, desear o aspirar a una meta, ya sea noble o indigna. En 1 Timoteo 3:1, Pablo elogia a quien aspira (ὀρέγω) al liderazgo en la iglesia. En 1 Timoteo 6:10 advierte que quienes se extienden hacia las riquezas se extravían de la fe. Hebreos 11:16 habla de los fieles que anhelaban una patria celestial. El verbo griego significa literalmente «estirar, alcanzar hacia», y en sentido figurado abarca el anhelo, la ambición y la aspiración profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3715', 'spa', 'Apetito, deseo o anhelo; impulso o inclinación hacia algo, especialmente ansia física o sensual', 'Este sustantivo denota deseo, apetito o anhelo intenso: un impulso que se extiende hacia el objeto deseado. Es el término griego general para la apetencia, abarcando diversas formas de deseo. En Romanos 1:27 describe un deseo sexual ilícito: «los hombres, dejando las relaciones naturales con la mujer, se encendieron en su deseo unos por otros». El vocablo enfatiza la intensidad: «se consumían de deseo». Aunque el término puede ser neutro (deseo de cosas buenas), aquí describe una pasión desordenada que viola el diseño creacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3716', 'spa', 'Caminar rectamente, conducirse conforme a normas de rectitud e integridad moral', 'Este verbo emplea la imagen de caminar en línea recta como metáfora de la rectitud moral. Pablo lo usa una sola vez en Gálatas para confrontar la conducta inconsistente de Pedro respecto a la comunión con los gentiles. La evidencia multilingüe, desde el español «rectamente» hasta el alemán «recht wandeln», confirma la imagen de una conducta recta e íntegra. El vocablo combina el sentido de rectitud física con integridad ética, cuestionando si las acciones de uno se alinean con la verdad del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3718', 'spa', 'cortar en línea recta, manejar con precisión (esp. la palabra de verdad de Dios)', 'Este verbo compuesto significa literalmente cortar en línea recta, como un albañil que coloca piedras o un agricultor que traza un surco. Pablo lo emplea metafóricamente en 2 Timoteo para exhortar a Timoteo a manejar las Escrituras con precisión e integridad. Los testimonios multilingües —el español ''trazando rectamente,'' el francés conservando el griego— resaltan la naturaleza técnica de esta palabra poco frecuente. Evoca la imagen de un artesano cuyos cortes rectos y cuidadosos distinguen el trabajo hábil de los atajos descuidados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3719', 'spa', 'madrugar, levantarse al alba para ir a algún lugar', 'Este verbo describe la acción de dirigirse a un lugar temprano por la mañana, llegando al amanecer. Lucas lo emplea para retratar a las multitudes de Jerusalén que acudían al templo al despuntar el alba para escuchar a Jesús enseñar durante su última semana. La palabra capta el entusiasmo de quienes se levantaban antes del amanecer para asegurarse un lugar cerca del Maestro, sugiriendo tanto devoción como expectativa. El término se relaciona con ὄρθρος (alba) y transmite el compromiso necesario para llegar cuando despunta la primera luz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3720', 'spa', 'temprano, perteneciente a la mañana o al alba', 'Este adjetivo describe lo que pertenece a las primeras horas de la mañana, justo después del amanecer. En el relato lucano de la resurrección, califica a las mujeres que llegaron al sepulcro ''de madrugada,'' captando ese momento en que la oscuridad cede ante la primera luz. La evidencia multilingüe —desde el español ''de madrugada'' hasta el francés ''matinal''— confirma el enfoque temporal en el alba. La palabra evoca ese instante liminal en que la noche da paso al día, particularmente significativo en un pasaje donde el amanecer literal acompaña el descubrimiento de un sepulcro vacío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3721', 'spa', 'al amanecer, por la mañana, temprano; matutino (como adjetivo)', 'Este adjetivo significa ''al amanecer'' o ''por la mañana'', y suele modificar verbos de movimiento o llegada: ''llegó temprano'', ''estar presente por la mañana''. Como adjetivo atributivo, describe cosas matutinas: la papilla de la mañana, el canto matutino. En la comedia se juega con su parecido a ὄρθιον (canto erguido). El canto madrugador del gallo se llama ὄρθριον ᾆσμα. El neutro τὸ ὄρθριον funciona adverbialmente: ''por la mañana''. El comparativo ὀρθρίτερον significa ''más temprano''. Evoca el comienzo fresco del día.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3722', 'spa', 'alba, amanecer, madrugada; el momento justo antes o al salir el sol', 'Este término designa el alba o la madrugada, el momento justo antes del amanecer o al despuntar el sol. Las mujeres llegaron al sepulcro «muy de madrugada» (Lucas 24:1). Jesús se presentó en el templo «al amanecer» (Juan 8:2). Los apóstoles entraron en el templo «al rayar el alba» para enseñar (Hechos 5:21). La palabra marca la parte más temprana del día, cuando la oscuridad cede paso a la luz. El griego ὄρθρος designa específicamente ese período de transición entre la noche y el día.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3723', 'spa', 'Correctamente, rectamente, con claridad; de manera recta o apropiada.', 'Adverbio que significa ''correctamente'' o ''rectamente,'' empleado en los Evangelios para afirmar que alguien ha hablado o respondido bien. Jesus dice al interprete de la ley ''Bien has respondido'' (Lc 10:28), y los fariseos reconocen que Jesus ensena ''rectamente,'' sin parcialidad (Lc 20:21). En Marcos 7:35 describe al hombre sanado hablando ''con claridad,'' pues su lengua funciona ya como debe. El termino abarca desde la correccion moral y doctrinal hasta la rectitud en el funcionamiento fisico del habla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3724', 'spa', 'Determinar, designar o declarar; fijar límites, ordenar acontecimientos o señalar personas según decisión divina o humana.', 'Enraizado en el sustantivo ὅρος (''límite''), este verbo porta el sentido espacial de marcar fronteras y el sentido metafórico de fijar, determinar u ordenar. En el Nuevo Testamento describe abrumadoramente la soberanía divina: Dios determinó los tiempos señalados y los límites de las naciones (Hch 17:26), y Jesús va ''según lo que ha sido determinado'' (Lc 22:22). Puede especificar la designación de una persona para un cargo, como cuando Jesús es ''designado juez de vivos y muertos'' (Hch 10:42). Su uso teológicamente más debatido es Romanos 1:4, donde Jesús es ''declarado'' o ''señalado'' como Hijo de Dios con poder, enfatizando una designación pública y autoritativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3725', 'spa', 'Región, frontera, límite territorial; los confines o el distrito de un lugar determinado.', 'Región, frontera, límite territorial; los confines o el distrito de un lugar determinado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3726', 'spa', 'conjurar, hacer jurar, poner bajo juramento solemne invocando a Dios o un nombre sagrado', 'Este verbo significa poner a alguien bajo juramento solemne o conjurarlo invocando un nombre divino o sagrado. En Marcos 5:7, el endemoniado conjura a Jesús por Dios mismo, mostrando la gravedad del juramento incluso en boca de un demonio. La palabra lleva un peso legal y sagrado: Pablo conjura a los tesalonicenses por el Señor a que su carta sea leída a todos (1 Ts 5:27), y exorcistas judíos intentan invocar el nombre de Jesús sobre demonios (Hch 19:13). Se trata fundamentalmente de compeler una acción o declaración mediante invocación sagrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3727', 'spa', 'Juramento, promesa solemne -- declaracion solemne que invoca a Dios como testigo, que obliga al jurante a cumplir una promesa. El sustantivo horkos (ὅ', 'Juramento, promesa solemne -- declaracion solemne que invoca a Dios como testigo, que obliga al jurante a cumplir una promesa. El sustantivo horkos (ὅρκος) designa una declaracion solemne jurada o voto vinculante, que tipicamente invoca a un testigo divino. Jesus aborda la tradicion del cumplimiento de juramentos: ''no juraras en falso, sino que cumpliras tus juramentos al Senor'' (Mateo 5:33), antes de exhortar a sus seguidores a no jurar en absoluto. El juramento precipitado de Herodes en el banquete de Herodias lo atrapo y lo obligo a ordenar la ejecucion del Bautista (Mateo 14:7,9). En el plano teologico mas profundo, Dios mismo juro un juramento a Abraham (Lucas 1:73; Hechos 2:30), y Hebreos argumenta que, como Dios no podia jurar por nadie mayor, juro por si mismo (Hebreos 6:16-17). El juramento funciona asi como la garantia suprema de la fidelidad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3728', 'spa', 'Juramento, acto de jurar; declaracion divina solemne y vinculante.', 'Sustantivo que aparece exclusivamente en Hebreos 7 y designa el acto formal de prestar juramento. El autor argumenta que el sacerdocio de Jesus es superior porque fue establecido ''con juramento'' (Heb 7:20-21), a diferencia de los sacerdotes leviticos que servian ''sin juramento.'' El climax llega en Hebreos 7:28, donde la ''palabra del juramento'' constituye al Hijo como sumo sacerdote permanente. Su uso concentrado en un solo capitulo subraya su peso teologico: el juramento de Dios es la garantia inquebrantable del sacerdocio del nuevo pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3729', 'spa', 'Lanzarse, precipitarse; ponerse en movimiento violento, a menudo como estampida o embestida.', 'Verbo que significa lanzarse hacia adelante impetuosamente, arremeter o precipitarse en estampida. Sus usos neotestamentarios son marcadamente dramaticos: los cerdos gadarenos ''se precipitaron'' por un despenadero hacia el mar (Mt 8:32; Mc 5:13; Lc 8:33), la multitud ''se lanzo'' sobre Esteban a una voz (Hch 7:57), y la turba efesia ''se precipito'' en el teatro (Hch 19:29). Derivado de ὁρμή (impulso, acometida), el verbo conlleva un sentido inherente de fuerza irresistible y movimiento incontrolado hacia adelante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3731', 'spa', 'ímpetu violento, impulso arrollador o embestida', 'Este sustantivo denota un movimiento repentino y poderoso de arrastre, ya sea de un ejército que ataca, un ave rapaz que se lanza en picada o una piedra arrojada por el aire. Apocalipsis lo emplea para describir la fuerza violenta con que cae la Babilonia simbólica. Las glosas en griego y alemán preservan la palabra misma (''Wucht''), mientras que el español y el francés captan la violencia y la fuerza involucradas. El término transmite tanto velocidad como poder destructivo, evocando imágenes de un impulso irresistible y catastrófico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3732', 'spa', 'ave, pájaro; criatura alada, especialmente en contextos de juicio e imaginería apocalíptica', 'Término sencillo para designar aves o pájaros, que aparece exclusivamente en las visiones apocalípticas del Apocalipsis. Las tres apariciones se sitúan en escenas de juicio: Babilonia se convierte en guarida de toda ave inmunda (Ap 18:2), y las aves son convocadas a devorar a los caídos en la gran cena de Dios (Ap 19:17, 21). Las traducciones multilingües lo vierten uniformemente como «ave(s)» o «pájaro(s)», reflejando su significado concreto y directo, aunque los contextos en que aparece son todo menos ordinarios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3734', 'spa', 'límites establecidos, fronteras fijadas (de tiempo, espacio o circunstancia)', 'Este sustantivo se refiere a fronteras que han sido deliberadamente establecidas o designadas. En Hechos, Pablo lo usa para describir el ordenamiento soberano de Dios sobre la habitación humana a lo largo del tiempo y la geografía. El término combina los conceptos de delimitación e intencionalidad divina. La evidencia multilingüe muestra consistencia: boundaries (inglés), límites (español), limite (francés). La palabra sugiere no fronteras aleatorias sino líneas trazadas con propósito que estructuran la existencia humana conforme a la sabiduría divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3735', 'spa', 'ὄρος — monte o cerro; elevación física y escenario de revelación divina', 'El sustantivo neutro ὄρος («monte, montaña») aparece 64 veces en el Nuevo Testamento, designando algunos de los paisajes con mayor carga teológica de la Escritura. Los montes sirven como escenarios de revelación y encuentro: el diablo lleva a Jesús a un monte muy alto (Mt 4:8), el Sermón del Monte se pronuncia desde uno (Mt 5:1), la Transfiguración tiene lugar en otro (Mt 17:1) y el Discurso del Olivete se desarrolla en el Monte de los Olivos (Mt 24:3). Pablo contrasta el monte Sinaí con la Jerusalén celestial (Gá 4:24-25), y el Apocalipsis contempla la nueva Jerusalén descendiendo vista desde un gran monte (Ap 21:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3736', 'spa', 'Cavar, excavar la tierra con fines agrícolas, de construcción o para ocultar algo', 'Verbo común en contextos agrícolas y de construcción que significa cavar o excavar la tierra. Jesús lo emplea dos veces en parábolas: el dueño de la viña que cavó un lagar para preparar su cultivo (Mt 21:33; Mr 12:1), y el siervo temeroso que cavó en la tierra para esconder el dinero de su señor (Mt 25:18). La palabra resalta un trabajo intencional sobre el suelo, ya sea con fines productivos como la viticultura o con fines defensivos como el ocultamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3738', 'spa', 'Bailar, danzar; movimiento corporal ritmico en contextos de celebracion, espectaculo o como contraparte del duelo.', 'Este verbo describe la accion de bailar o danzar en contextos tanto festivos como parabolicos. En la parabola del mercado que narra Jesus (Mt 11:17; Lc 7:32), los ninos se quejan: ''Os tocamos la flauta y no bailasteis''; aqui la danza representa la respuesta gozosa que la gente se nego a dar. En el banquete de Herodes, la hija de Herodias ''danzo'' de manera tan provocativa que logro la ejecucion de Juan el Bautista (Mt 14:6; Mc 6:22). El termino abarca desde el juego infantil inocente hasta el espectaculo peligroso y seductor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3739', 'spa', 'Pron. relativo: quien, cual, que; tambien relativo indefinido quienquiera/cualquiera; correlativo uno...otro; rara vez ''donde''.', 'El pronombre relativo griego hos (con su paradigma completo de caso, genero y numero) es el recurso principal de subordinacion en el Nuevo Testamento, introduciendo clausulas relativas que identifican, describen y especifican a sus antecedentes. Aparece mas de 1.400 veces y en la mayoria de los casos funciona como relativo definido: ''el que,'' ''lo cual,'' ''el lugar que.'' Dos usos secundarios merecen atencion: combinado con an o ean, se generaliza en relativo indefinido (''quienquiera que,'' ''cualquier cosa que,'' Mt 10:27), y en la construccion pareada hos men...hos de se convierte en pronombre correlativo-distributivo: ''uno...otro,'' ''unos...otros,'' visible en la Parabola del Sembrador (Mt 13:4-8). Un punado de ocurrencias adquiere valor locativo: ''donde.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3740', 'spa', 'Cuantas veces, cada vez que; conjunción correlativa que indica frecuencia de una acción repetida', 'Conjunción temporal que significa «cuantas veces» o «cada vez que», y que señala la repetición de una acción. Pablo la usa dos veces en sus instrucciones sobre la Cena del Señor, subrayando que «cuantas veces» los creyentes beban de la copa o coman del pan, proclaman la muerte del Señor (1 Co 11:25-26). En Apocalipsis describe la frecuencia con que los dos testigos pueden cerrar el cielo o herir la tierra «cuantas veces» quieran (Ap 11:6). El término destaca no solo la repetición, sino la correlación entre el momento y la trascendencia de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3741', 'spa', 'Santo, devoto, piadoso; consagrado o sancionado por ley divina; cosas santas o promesas sagradas', 'El adjetivo ὅσιος describe aquello que ha sido sancionado o consagrado por ordenanza divina, ocupando un espacio semántico distintivo entre δίκαιος (justo según la ley humana) e ἱερός (sagrado para Dios). En el Nuevo Testamento aparece con mayor frecuencia como título cristológico, «el Santo», aplicado a Cristo, especialmente en las citas de los Salmos en Hechos 2:27 y 13:35, donde la promesa de Dios de no permitir que su Santo vea corrupción se convierte en piedra angular de la predicación de la resurrección. También describe el carácter personal del creyente devoto, como en Tito 1:8, donde el anciano debe ser ὅσιος. Un uso menos frecuente en neutro plural (Hechos 13:34) se refiere a «las cosas santas» o promesas sagradas dadas a David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3743', 'spa', 'de manera santa, devotamente, piadosamente', 'Este adverbio describe una conducta caracterizada por la reverencia hacia Dios y la conformidad con las normas divinas de pureza. Pablo lo emplea una sola vez para recordar a los tesalonicenses cuán irreprochablemente se comportaron él y sus compañeros entre ellos. El término deriva de ὅσιος (santo, consagrado) y enfatiza un comportamiento sancionado por la ley divina, no meramente por la costumbre humana. Sugiere una vida vivida conscientemente ante Dios, donde las acciones se alinean con lo que es sagrado y agradable a él.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3744', 'spa', 'Olor, fragancia, aroma; un aroma percibido por el olfato, especialmente un olor agradable ofrecido a Dios', 'La palabra griega estándar para cualquier olor, pero en el NT aparece exclusivamente en contextos positivos, a menudo cúlticos. La frase «aroma fragante» (ὀσμὴ εὐωδίας) evoca la expresión veterotestamentaria de un sacrificio cuyo olor agrada a Dios. Pablo aplica esta imagen a la ofrenda de Cristo (Ef 5:2), al generoso regalo de los filipenses (Fil 4:18) y, de manera sorprendente, al propio ministerio apostólico como «fragancia de Cristo» que difunde el conocimiento de Dios (2 Cor 2:14-16). Juan 12:3 ofrece el único uso no metafórico: la casa se llenó de la fragancia del costoso nardo de María.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3745', 'spa', 'Pronombre correlativo: «cuantos, cuanto, todo el que, lo que»; marca cantidad, extensión, grado o duración', 'Este versátil pronombre correlativo es la herramienta principal del griego para expresar cantidad y extensión relativa. En su uso más frecuente, reúne un conjunto entero de cosas o personas: «todos los que creyeron» (Hch 4:34), «todo lo que queráis» (Mt 7:12). También funciona proporcionalmente («en cuanto», Mt 25:40), exclamativamente («¡cuántas cosas!», Mc 5:19-20) o temporalmente («mientras», Ro 7:1). Su alcance, desde la aritmética cotidiana hasta la proporcionalidad escatológica, lo convierte en uno de los engranajes silenciosos del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3746', 'spa', 'el mismo que, precisamente quien (pronombre relativo intensivo ὅσπερ = ὅς + περ); a menudo equivale al simple ὅς', 'El pronombre relativo ὅς, reforzado con la partícula intensiva περ, forma ὅσπερ: ''precisamente quien'' o ''el mismo que''. Con frecuencia resulta indistinguible del simple ὅς, pero la partícula περ añade énfasis o precisión. Aparece tras adjetivos de semejanza: ''las mismas cosas que'' o ''similar a lo que''. Homero lo emplea así: ''el mismo hombre que golpeó'' (ὅς ῥ᾽ ἔβαλέν περ). Los casos oblicuos a veces toman formas del artículo (τόπερ), especialmente en textos jónicos y poéticos. La construcción subraya identidad o correspondencia exacta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3747', 'spa', 'Hueso, huesos; la estructura osea del cuerpo, usada literalmente de restos fisicos y figuradamente de union intima.', 'Sustantivo neutro que significa hueso o huesos, presente en contextos tanto literales como figurados en el NT. Jesus apela a sus huesos fisicos para demostrar su resurreccion corporal: ''un espiritu no tiene carne ni huesos como veis que yo tengo'' (Lc 24:39). En Mt 23:27, los sepulcros blanqueados estan ''llenos de huesos de muertos'', imagen de impureza oculta. Jn 19:36 aplica el Salmo 34:20 a la crucifixion: ''no sera quebrado hueso suyo''. Efesios 5:30 evoca Genesis 2:23 para describir a los creyentes como ''hueso de sus huesos'', expresando union profunda con Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3748', 'spa', 'Pronombre relativo indefinido: «quien, el cual, quienquiera que»; a veces generalizante: «cualquiera que»', 'Pronombre relativo compuesto (formado por ὅς + τις) que porta una fuerza sutilmente distinta del relativo simple ὅς. En su uso estándar —la gran mayoría de sus 140 apariciones neotestamentarias— introduce cláusulas relativas como un simple «quien» o «el cual», identificando o describiendo personas y cosas (Mt 7:15; 16:28). Pero su componente indefinido aflora en una función generalizante que significa «quienquiera que» o «cualquiera que», confiriendo a la cláusula un alcance condicional o universal. El español capta bien este desplazamiento, pasando de «los cuales / quienes» en el sentido específico a «cualquiera que» en el generalizante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3750', 'spa', 'sentido del olfato, facultad u órgano olfativo', 'Este sustantivo designa la capacidad de oler o el órgano físico responsable de detectar aromas. Pablo lo emplea en una pregunta retórica sobre la diversidad de funciones corporales dentro de la iglesia concebida como un solo cuerpo. El término puede referirse tanto a la facultad olfativa como a la nariz en cuanto aparato de percepción. El argumento de Pablo es que un cuerpo compuesto enteramente de un solo sentido sería absurdamente incompleto, subrayando así la necesidad de diversidad de dones espirituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3751', 'spa', 'Los lomos o región de la cintura; designa tanto el torso inferior (ceñido para la acción) como, por metonimia, la fuerza procreadora', 'Ὀσφύς se refiere a la parte baja de la espalda y la zona de las caderas: los lomos. En la cultura antigua, ceñirse los lomos significaba recoger la vestimenta para trabajar o viajar, y esta imagen impregna el NT: el cinturón de cuero de Juan el Bautista alrededor de su cintura (Mt 3:4, Mc 1:6), el llamado a estar preparados en Lucas 12:35 y el «cinturón de la verdad» en Efesios 6:14. Pero ὀσφύς también conlleva una metáfora reproductiva: Hechos 2:30 habla de uno que vendría «del fruto de sus lomos» de David, haciendo eco del modismo hebreo para referirse a los descendientes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3752', 'spa', 'Cuando, siempre que — conjunción temporal que introduce eventos futuros indefinidos o condiciones recurrentes', 'ὅταν es una contracción de ὅτε («cuando») más ἄν (la partícula de contingencia), produciendo una conjunción que significa «cuando» o «siempre que» con un elemento de indefinición o futuridad. A diferencia del simple ὅτε, que puede señalar un evento pasado definido, ὅταν apunta típicamente hacia algo esperado o recurrente. Jesús la emplea con frecuencia en el Sermón del Monte para describir situaciones habituales: «cuando ores» (Mt 6:5-6), «cuando ayunes» (Mt 6:16). También introduce condiciones escatológicas: «cuando venga el Hijo del Hombre» (Mt 25:31). El español «cuando» la traduce de forma consistente en sus 123 apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3753', 'spa', 'Cuando, en el momento en que; adverbio relativo temporal que introduce cláusulas de tiempo pasado o futuro', 'ὅτε es un adverbio relativo temporal que significa «cuando» o «en el momento en que», formado a partir de la raíz relativa ὁ- y la partícula τε. Introduce cláusulas subordinadas que sitúan acciones en el tiempo, típicamente con el modo indicativo para eventos pasados. En los Evangelios marca transiciones narrativas con frecuencia: «cuando Jesús terminó estas palabras» (Mt 7:28), «cuando la multitud fue echada fuera» (Mt 9:25). Responde al demostrativo τότε («entonces») y al interrogativo πότε («¿cuándo?»). El español «cuando» lo traduce de manera uniforme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3754', 'spa', 'Conjuncion: que (clausulas de contenido); porque, pues (causal); rara vez relativo: lo que, cualquier cosa que.', 'La conjuncion griega hoti es una de las palabras mas frecuentes del Nuevo Testamento, con mas de 1.300 ocurrencias y dos funciones principales que solo el contexto permite distinguir. Tras verbos de decir, saber o percibir, introduce una clausula de contenido: ''que'' (Jesus dijo que, ellos sabian que, el percibio que). Pero hoti tambien introduce clausulas causales: ''porque'' o ''pues,'' como en las Bienaventuranzas: ''Bienaventurados los de limpio corazon, porque ellos veran a Dios'' (Mt 5:8). El espanol ''que'' refleja fielmente esta ambiguedad, mientras que el aleman distingue dass (contenido) frente a weil/denn (causa), obligando al traductor a decidir. Un reducido grupo de ocurrencias conserva la construccion relativa arcaica ho ti: ''lo que'' o ''cualquier cosa que'' (Mc 6:23; Jn 14:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3755', 'spa', 'Quienquiera que, cualquiera que; pronombre relativo indefinido con frecuente valor temporal o condicional.', 'Pronombre relativo indefinido (forma genitiva masculina singular de ὅστις) que significa ''de quienquiera'' o ''hasta que''. Combina el relativo ὅς con el indefinido τις para crear una referencia generalizadora. En el NT predomina su uso temporal o condicional: ''hasta que se cumpla'' (Lc 12:50), ''hasta que de fruto'' (Lc 13:8), ''hasta que se cumpla'' (Lc 22:16). Mt 5:25 lo emplea en una clausula temporal urgente (''mientras estas en el camino''). En espanol, la conjuncion ''que'' o las locuciones ''hasta que'' y ''mientras'' captan este sentido durativo-condicional que se adhiere frecuentemente al pronombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3756', 'spa', 'ou: particula griega de negacion objetiva que niega hechos y enunciados.', 'La particula ou (con sus variantes fonologicas ouk ante espiritu suave y ouch ante espiritu aspero) es la negacion griega estandar para enunciados facticos en modo indicativo. Contrasta nitidamente con me, que niega deseos, mandatos e hipotesis: donde me dice ''que no sea asi,'' ou declara rotundamente ''no es asi.'' Con 1.635 ocurrencias en el Nuevo Testamento, constituye un elemento gramatical esencial: niega verbos, modifica adjetivos y forma preguntas retoricas que esperan respuesta afirmativa. El espanol ''no,'' el frances ''ne...pas'' y el aleman ''nicht'' corresponden uniformemente a esta unica funcion, confirmando su caracter monosemico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3757', 'spa', 'Derivado del genitivo del pronombre relativo ὅς, este pequeño adverbio cumple un trabajo esencial tanto en la narración como en la instrucción. Señala', 'Derivado del genitivo del pronombre relativo ὅς, este pequeño adverbio cumple un trabajo esencial tanto en la narración como en la instrucción. Señala el lugar donde algo sucede: la estrella ''se detuvo sobre el lugar donde estaba el niño'' (Mt 2:9), ''donde dos o tres están congregados en mi nombre'' (Mt 18:20), y el monte ''al que Jesús les había indicado'' (Mt 28:16). En Lucas ancla a Jesús en la sinagoga de su pueblo natal: ''donde se había criado'' (Lc 4:16). El español ''donde'' refleja con exactitud su función locativa simple en cada aparición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3758', 'spa', '¡Ah! ¡Ja! (exclamación de burla, ironía o asombro)', 'Esta interjección expresa una emoción intensa: a veces admiración, pero más frecuentemente burla o sorpresa irónica. Marcos la registra en labios de quienes se mofaban de Jesús en la cruz. La partícula, tomada del latín (''vah!''), funciona en diversas lenguas con mínima variación. Es el equivalente verbal de un gesto despectivo, cargado de desdén. La brevedad de la palabra contrasta con la virulencia del contexto, donde líderes religiosos se burlan de un hombre moribundo, sin percatarse de la ironía profética de sus propias palabras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3759', 'spa', 'οὐαί — ¡ay!; exclamación de dolor, advertencia o denuncia profética contra personas, ciudades o conductas', 'οὐαί — ¡ay!; exclamación de dolor, advertencia o denuncia profética contra personas, ciudades o conductas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3760', 'spa', 'de ningún modo, en absoluto, de ninguna manera', 'Este adverbio negativo enfático niega rotundamente una proposición. En Mateo aparece en una cita del profeta Miqueas, donde se insiste en que Belén de ningún modo es la menor entre los gobernantes de Judá. El término funciona retóricamente para introducir una corrección o contradicción. Es el equivalente griego de «en absoluto» o «de ninguna manera», y suele aparecer en respuestas o declaraciones para descartar de raíz una afirmación errónea, subrayando que las apariencias engañan respecto al plan redentor de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3761', 'spa', 'Conjunción negativa «ni, tampoco» o adverbio enfático «ni siquiera», que extiende o intensifica una negación', 'Una partícula negativa de doble función en el Nuevo Testamento. Como conjunción encadena negaciones — «ni», «y no», «tampoco» — enlazando elementos ya bajo un paraguas negativo (Mt 6:26: «no siembran, ni siegan, ni recogen en graneros»). Como adverbio enfático agudiza la negación a «ni siquiera», subrayando que incluso el caso más esperable falla (Mt 6:29: «ni aun Salomón con toda su gloria»). El español distingue bien ambas funciones: «ni» para la conjuntiva y «ni aun / ni siquiera / tampoco» para la enfática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3762', 'spa', 'Nadie, ninguno, nada; pronombre negativo fuerte que niega personas o cosas de manera absoluta', 'οὐδείς es el pronombre negativo enfático del griego, compuesto de οὐ («no») y εἷς («uno»), que niega categóricamente la existencia de cualquier persona o cosa dentro del alcance de la afirmación. Es la palabra detrás de algunas de las declaraciones más absolutas del Nuevo Testamento: «Nadie viene al Padre sino por mí» (Jn 14:6), «Nadie puede servir a dos señores» (Mt 6:24), «No hay justo, ni aun uno» (Ro 3:10). Su fuerza es mayor que la del simple οὐ con un indefinido: afirma una negación total y universal. El español distingue nadie (personas) de nada (cosas), como el alemán niemand frente a nichts.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3763', 'spa', 'Nunca; en ningún momento. Negación temporal enfática compuesta de οὐδέ (''ni siquiera'') y ποτέ (''en algún momento''), que niega de forma absoluta que al', 'Nunca; en ningún momento. Negación temporal enfática compuesta de οὐδέ (''ni siquiera'') y ποτέ (''en algún momento''), que niega de forma absoluta que algo haya ocurrido o vaya a ocurrir. Jesús la emplea en sus declaraciones más solemnes: ''Nunca os conocí'' (Mt 7:23) y ''¿Nunca leísteis?'' como reproche retórico (Mt 21:16, 42). La promesa impetuosa de Pedro, ''Nunca me apartaré'' (Mt 26:33), y el asombro de la multitud, ''Nunca se ha visto cosa semejante en Israel'' (Mt 9:33), ilustran su fuerza absoluta e incondicional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3764', 'spa', 'Todavia no, aun no; indica algo anticipado pero que aun no se ha realizado o experimentado.', 'Adverbio de negacion temporal que indica que un estado o acontecimiento esperado aun no se ha cumplido. El Evangelio de Juan lo emplea de manera incisiva: el Espiritu ''todavia no'' habia sido dado porque Jesus aun no habia sido glorificado (Jn 7:39), y los discipulos ''todavia no'' entendian la Escritura acerca de la resurreccion (Jn 20:9). En Jn 19:41 describe un sepulcro donde ''nadie habia sido puesto todavia''. Hch 8:16 senala que el Espiritu ''todavia no'' habia descendido sobre los samaritanos. El espanol ''todavia no'' preserva fielmente la expectativa temporal inherente al adverbio griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3765', 'spa', 'Ya no, nunca más — adverbio temporal negativo que marca el cese de un estado previo', 'Οὐκέτι (compuesto de οὐκ + ἔτι, «no» + «todavía/aún») señala que algo que antes era vigente ha dejado de serlo. Sus 50 apariciones neotestamentarias marcan transiciones decisivas: lo que Dios unió, el hombre «ya no» lo separe (Mt 19:6); tras la Transfiguración, los discípulos «ya no» vieron a nadie sino a Jesús solo (Mc 9:8); el hijo pródigo se declara «ya no» digno de ser llamado hijo (Lc 15:19, 21); y el Cristo resucitado «ya no» muere (Ro 6:9). El adverbio conlleva una narrativa implícita de cambio —un antes y un después— que lo convierte en pieza clave de la teología de la conversión, la muerte-resurrección y el nuevo pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3766', 'spa', 'así que, entonces, por consiguiente', 'Esta partícula inferencial extrae una conclusión o invita al acuerdo con una consecuencia lógica. En el Evangelio de Juan, Pilato la emplea al interrogar a Jesús sobre su realeza: «¿Así que tú eres rey?» La partícula combina οὐκ y οὖν para crear un tono de indagación apremiante o deducción lógica. Funciona como marcador discursivo que señala que el hablante está construyendo o confirmando una inferencia a partir de lo dicho previamente, presionando hacia una respuesta directa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3767', 'spa', 'Por tanto, entonces, así pues — conjunción inferencial que extrae una conclusión lógica de lo precedente', 'οὖν es la partícula inferencial primaria del Nuevo Testamento, con 505 apariciones que señalan que lo que sigue es consecuencia, conclusión o paso siguiente en un argumento o narración. En los Evangelios suele avanzar la trama («entonces dijo Jesús»), mientras que en las Epístolas marca inferencia lógica («por tanto, habiendo sido justificados por la fe», Ro 5:1). Su tono va desde la transición narrativa ligera hasta la convocatoria teológica solemne. Las traducciones lo captan bien: el español «pues», «por tanto» y «así que» marcan secuencia lógica o temporal, no contraste adversativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3768', 'spa', 'Todavía no; adverbio temporal negativo que indica que un estado o evento no ha ocurrido hasta el momento presente.', 'Todavía no; adverbio temporal negativo que indica que un estado o evento no ha ocurrido hasta el momento presente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3769', 'spa', 'Cola; la cola de una criatura, usada en Apocalipsis para colas de escorpion y serpiente que ejercen poder destructivo.', 'Sustantivo femenino que significa cola, usado exclusivamente en Apocalipsis para describir los aterradores apendices de criaturas apocalipticas. Las langostas de la quinta trompeta tienen colas semejantes a escorpiones con aguijones que atormentan durante cinco meses (Ap 9:10). Los caballos de la sexta trompeta poseen colas como serpientes, con cabezas que causan dano (Ap 9:19). La cola del gran dragon rojo arrastra la tercera parte de las estrellas del cielo (Ap 12:4). En estos contextos, la palabra esta cargada de amenaza simbolica y poder destructor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3770', 'spa', 'Celestial; que pertenece al cielo o proviene de él; relativo a la morada de Dios o al ámbito divino', 'Describe lo que pertenece al cielo o tiene su origen en el ámbito divino. En los Evangelios, Jesús emplea este adjetivo exclusivamente en relación con el Padre — «vuestro Padre celestial» (Mt 6:14, 6:26, 6:32) — estableciendo un contraste entre la ansiedad terrenal y la generosa provisión de Dios que habita en lo alto. La evidencia multilingüe es notablemente uniforme: el español «celestial», el francés «céleste» y el alemán «himmlisch» convergen todos en un sentido único, confirmando que esta palabra mantuvo un significado estable a lo largo del Nuevo Testamento sin oscilar entre un uso cosmológico literal y una metáfora teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3772', 'spa', 'Cielo, cielos; la bóveda visible sobre la tierra y la morada trascendente o reino de Dios', 'El griego οὐρανός abarca dos zonas conceptuales que el español reúne en una sola palabra: cielo. En sus 278 apariciones neotestamentarias puede designar la extensión física donde vuelan las aves y brillan los astros (Mt 6:26), el firmamento que un día pasará (Mt 5:18), o la morada trascendente de Dios y destino de los fieles (Mt 6:20). Jesús lo empareja frecuentemente con la tierra para abarcar toda la realidad: «Hágase tu voluntad, como en el cielo, así también en la tierra» (Mt 6:10). La misma ambigüedad productiva entre lo físico y lo divino se conserva en francés ciel y en alemán Himmel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3773', 'spa', 'Urbano (nombre personal latino, que significa ''de la ciudad'')', 'Esta es la forma griega del nombre latino Urbanus, que significa ''urbano'' o ''de la ciudad''. Pablo envía saludos a este individuo en su carta a los Romanos, identificándolo como ''nuestro colaborador en Cristo''. El nombre sugiere ciudadanía romana u orígenes urbanos, algo común entre esclavos y libertos en la capital imperial. Que Pablo lo llame colaborador indica una participación activa en el ministerio. El nombre aparece con ligeras variaciones según las convenciones de transliteración de cada idioma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3774', 'spa', 'Urías (nombre personal hebreo, ''YHWH es mi luz'')', 'Esta es la forma griega del nombre hebreo Urías, llevado más célebremente por el guerrero hitita cuya esposa Betsabé fue tomada por el rey David. Mateo lo incluye en la genealogía de Jesús, uno de los pocos nombres mencionados junto a un escándalo moral. El nombre significa ''YHWH es mi luz'', un eco irónico dado cómo el pecado de David proyectó oscuridad sobre el hogar de Urías. La genealogía no oculta la sórdida historia sino que la integra, mostrando que el linaje del Mesías incluye tanto a pecadores como a víctimas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3775', 'spa', 'oído — el órgano físico de la audición, usado literal y figuradamente para la receptividad o el rechazo espiritual', 'oído — el órgano físico de la audición, usado literal y figuradamente para la receptividad o el rechazo espiritual');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3777', 'spa', 'Ni... ni; conjunción negativa correlativa que coordina cláusulas o elementos negados', 'Οὔτε es la conjunción negativa correlativa griega, empleada típicamente en construcciones pareadas (οὔτε...οὔτε) para negar dos o más elementos coordinados: «ni... ni». Jesús enseña que el tesoro celestial no sufre «ni» polilla «ni» óxido (Mt 6:20), y que la blasfemia contra el Espíritu no será perdonada «ni» en este siglo «ni» en el venidero (Mt 12:32). Pablo despliega extensas cadenas de οὔτε para catalogar todo lo que no puede separar a los creyentes del amor de Dios (Ro 8:38-39). La conjunción muestra una consistencia notable en sus 87 apariciones, y las traducciones la vierten uniformemente con negativas correlativas: «ni» en español y en francés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3778', 'spa', 'Este, esta, esto, estos: pronombre demostrativo de proximidad para personas, cosas y construcciones explicativas.', 'El pronombre demostrativo οὗτος (masculino), αὕτη (femenino), τοῦτο (neutro) es el recurso principal del Nuevo Testamento griego para senalar lo cercano, presente o recien mencionado. Refiere a cosas y situaciones (''por esto,'' Mt 6:25), identifica personas concretas (''este es aquel de quien esta escrito,'' Mt 11:10), y ocasionalmente introduce glosas explicativas: τοῦτ᾽ ἔστιν, ''esto es'' o ''es decir'' (Ro 9:8). La distincion entre su referencia a cosas y su referencia a personas queda confirmada por los patrones de traduccion multilingue.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3779', 'spa', 'Así, de este modo — adverbio demostrativo de manera que señala cómo se realiza o acontece algo', 'Οὕτως (ante consonante οὕτω) es el adverbio demostrativo derivado de οὗτος («este»), con el significado de «de este modo» o «así». Introduce o concluye comparaciones y analogías con frecuencia: «Porque de tal manera amó Dios al mundo» (Jn 3:16), donde intensifica el modo del amor divino. También funciona como conector discursivo que resume lo precedente («así sucedió») o anticipa lo que sigue. Jesús lo emplea repetidamente en el Sermón del Monte para trazar paralelos morales (Mt 5:12, 16). El francés ainsi y el alemán so confirman una función demostrativa de manera única y constante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3780', 'spa', '¿No? ¿Acaso no? — partícula negativa retórica que espera una respuesta afirmativa', 'Οὐχί es una forma intensificada del negativo griego οὐ, empleada casi exclusivamente en preguntas retóricas que esperan la conformidad del oyente: «¿No hacen lo mismo los publicanos?» (Mt 5:46). Sus 53 apariciones se concentran abrumadoramente en el discurso directo: Jesús interpelando a sus oyentes, Pablo presionando un argumento o un narrador planteando una pregunta incisiva. La fuerza retórica transforma la negación en afirmación: al preguntar «¿acaso no es así?», el hablante obliga al asentimiento. El español lo capta con «¿(acaso) no...?», mecanismo propio para señalar que una pregunta negativa espera respuesta positiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3781', 'spa', 'Deudor, el que debe; usado literalmente para deuda económica y figuradamente para obligación moral o espiritual', 'ὀφειλέτης designa a alguien que está bajo obligación, ya sea monetaria o moral. En el Padrenuestro (Mt 6:12) ''nuestros deudores'' son aquellos que han pecado contra nosotros, fusionando deuda económica y moral en una sola imagen. La parábola del siervo que no perdona (Mt 18:24) presenta a un deudor que debe diez mil talentos, una suma absurdamente enorme destinada a ilustrar la deuda impagable del pecado ante Dios. Pablo se declara ''deudor'' tanto a griegos como a bárbaros (Ro 1:14), expresando su obligación de predicar el evangelio a todos. La ambigüedad entre lo financiero y lo moral hace de este término un vocablo teológicamente fecundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3782', 'spa', 'Deuda, lo que se debe; obligación financiera o deber moral', 'Este sustantivo designa aquello que se adeuda, ya sea una deuda en sentido económico o una obligación en sentido moral. En la parábola de Mateo, al siervo se le perdona su deuda (Mt 18:32). Pablo lo emplea tanto en sentido literal, instando a pagar lo que se debe a las autoridades (Ro 13:7), como en sentido figurado para referirse al deber conyugal que los esposos se deben mutuamente (1 Co 7:3). El término tiende un puente entre lo económico y lo ético, recordándonos que las obligaciones, sean monetarias o relacionales, tienen un peso real y exigen cumplimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3784', 'spa', 'Deber; estar obligado — moral (deber, tener que) o financieramente (adeudar una deuda)', 'Deber; estar obligado — moral (deber, tener que) o financieramente (adeudar una deuda)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3785', 'spa', '¡Ojalá! ¡Quién pudiera!; partícula exclamativa que expresa un deseo intenso, a menudo irrealizable.', 'Interjección (históricamente una forma verbal de ''deber'') que expresa un anhelo ferviente, con frecuencia teñido de ironía o frustración. Pablo la emplea con retórica incisiva: ''¡Ojalá reinaseis de veras!'' (1 Co 4:8), ''¡Ojalá me toleraseis un poco!'' (2 Co 11:1) y, de modo más impactante, ''¡Ojalá se mutilasen los que os perturban!'' (Gá 5:12). En Ap 3:15 Cristo exclama: ''¡Ojalá fueses frío o caliente!'' El español ''ojalá'', del árabe ''si Dios quiere'', refleja magistralmente la fuerza optativa del griego. Cada aparición conlleva una carga emocional que trasciende con mucho el simple deseo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3786', 'spa', 'Provecho, ventaja, beneficio; lo que es útil o valioso, frecuente en preguntas retóricas sobre el valor real', 'Significa provecho o ventaja, y aparece en penetrantes preguntas retóricas sobre el beneficio genuino. Pablo pregunta: «¿Qué provecho hay si los muertos no resucitan?» (1 Co 15:32). Santiago desafía dos veces a sus lectores respecto a una fe vacía: «¿De qué provecho es si alguien dice tener fe pero no tiene obras?» (Stg 2:14, 16). El término va más allá de las apariencias para indagar qué es lo que verdaderamente ayuda o beneficia. Originalmente denotaba ayuda o adelanto en el griego clásico, y conlleva un sentido de ventaja práctica y tangible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3788', 'spa', 'Ojo, ojos — el órgano de la vista; figuradamente, percepción espiritual, disposición moral o foco de deseo y juicio', 'Ὀφθαλμός abarca territorio literal y figurado a lo largo de sus 100 apariciones neotestamentarias. Físicamente designa el órgano de la vista en los relatos de sanación: Jesús toca ojos ciegos y estos ven (Mt 9:29-30; Jn 9:6). En sentido figurado, Jesús llama al ojo «la lámpara del cuerpo», por donde entra luz u oscuridad en toda la persona (Mt 6:22-23). Pablo ora para que «los ojos de vuestro corazón» sean iluminados (Ef 1:18), mientras que el «ojo malo» en el modismo semítico señala envidia o mezquindad (Mt 20:15; Mr 7:22). El ojo se convierte así en ventana a la condición moral y espiritual del ser humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3789', 'spa', 'Serpiente, culebra — reptil usado tanto en sentido literal como simbólico para representar astucia, maldad y engaño satánico.', 'Serpiente, culebra — reptil usado tanto en sentido literal como simbólico para representar astucia, maldad y engaño satánico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3790', 'spa', 'ceja (de un monte), borde o cresta escarpada', 'Aunque en el griego clásico esta palabra significa principalmente ''ceja'' del rostro, en Lucas designa la ceja o borde de un monte, el filo escarpado donde la pendiente se quiebra abruptamente. Lucas describe cómo la turba de Nazaret llevó a Jesús hasta la ceja del monte sobre el que estaba edificada su ciudad, con la intención de despeñarlo. El término evoca un borde precipitoso, un lugar de peligro donde un paso en falso significa una caída mortal. Las traducciones en diversos idiomas reflejan esta transferencia metafórica del rasgo facial al accidente geográfico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3791', 'spa', 'atormentado, acosado, perturbado por enfermedad o aflicción', 'Este verbo describe el estado de ser atormentado, perturbado o afligido, generalmente por enfermedad, opresión demoníaca o acoso externo. Hechos lo usa para describir a personas atormentadas por espíritus inmundos. La idea fundamental implica ser sacudido, alterado o sumido en desorden. La forma pasiva sugiere que la persona sufre la acción de fuerzas externas, ya sean espirituales o físicas, que le arrebatan la paz y la integridad. El contexto bíblico contrasta esta perturbación con la restauración que trae el poder de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3792', 'spa', 'formar un tumulto, reunir una turba alborotadora', 'Este verbo compuesto significa crear o reunir una turba, típicamente con fines violentos o sediciosos. Hechos lo utiliza para describir cómo los opositores en Tesalónica reclutaron alborotadores para provocar disturbios civiles contra Pablo y Silas. La palabra combina ''multitud'' (ὄχλος) con ''hacer'' (ποιέω), denotando manipulación deliberada de la muchedumbre. Sugiere agitación organizada en lugar de una congregación espontánea: alguien está fabricando el caos. El término captura la peligrosa intersección entre la oposición religiosa y el desorden civil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3793', 'spa', 'Multitud, muchedumbre, gentío — una masa de personas reunidas, especialmente las que siguen a Jesús o se congregan en público', 'El griego ὄχλος es la palabra de los Evangelios para las muchedumbres apremiantes, curiosas y a veces volubles que rodean a Jesús. Hereda del griego clásico un matiz ligeramente populista, incluso despectivo, donde ὄχλος podía significar «turba» en contraste con δῆμος («el pueblo»). En el Nuevo Testamento, la multitud sigue a Jesús para ser sanada (Mt 14:14), le impide el acceso (Mr 2:4) y finalmente cambia de lealtad en el juicio (Mt 27:20). Lucas y Hechos también lo emplean para reuniones urbanas generales. El francés foule y el alemán Volksmenge captan el sentido de una masa indiferenciada, distinta de una asamblea organizada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3794', 'spa', 'fortaleza, plaza fuerte, lugar fortificado', 'Este sustantivo designa una fortaleza o plaza fuerte militar, un lugar fortificado contra el ataque. Pablo lo emplea metafóricamente en 2 Corintios para describir fortalezas ideológicas: bastiones mentales de orgullo y razonamiento falso que resisten el conocimiento de Dios. La imagen militar es deliberada: no se trata de refugios endebles, sino de posiciones atrincheradas que requieren poder divino para ser derribadas. El término evoca muros altos, posiciones defensivas y resistencia obstinada contra la verdad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3795', 'spa', 'Pescadito, pez pequeño preparado; diminutivo que designa pescado cocido servido como acompañamiento del pan.', 'Diminutivo de ὄψον (alimento cocinado, condimento) que designa un pescado pequeño o preparado, consumido típicamente como acompañamiento del pan. Sus cinco apariciones se encuentran exclusivamente en el Evangelio de Juan, en dos escenas de alimentación. En la multiplicación de los cinco mil, un muchacho ofrece cinco panes de cebada y dos ὀψάρια (Jn 6:9, 11). En el desayuno junto al lago tras la resurrección, Jesús tiene pescado sobre las brasas (Jn 21:9), pide a los discípulos que traigan de su pesca (21:10) y les sirve pan y pescado (21:13). El español ''pescaditos'' conserva bellamente la cualidad diminutiva del original griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3796', 'spa', 'Tarde, al atardecer; después de mucho tiempo; indica la parte final o tardía de un día o período.', 'Adverbio de tiempo que indica tardanza: ya sea al caer la tarde o tras un intervalo considerable. Su uso teológicamente más significativo es Mt 28:1, donde ''tarde del sábado'' marca la transición hacia la mañana de la resurrección, pasaje muy debatido sobre si significa ''pasado el sábado'' o ''al atardecer del sábado''. En Mc 11:11 y 11:19 simplemente señala que Jesús abandona el templo ''al anochecer'', y Mc 13:35 enumera ''la tarde'' entre las vigilias de la noche. El español ''tarde'' transmite con naturalidad esta noción temporal, aunque el uso en Mt 28:1 sigue siendo uno de los célebres problemas cronológicos del Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3797', 'spa', 'lluvia tardía, lluvia de primavera (término agrícola)', 'Este adjetivo describe las lluvias tardías o primaverales, cruciales para llevar los cultivos a su madurez en el ciclo agrícola mediterráneo. Santiago lo emplea en una exhortación a la paciencia, señalando al labrador que espera tanto la lluvia temprana como la tardía. El término distingue las lluvias de primavera (marzo-abril) de las lluvias otoñales que inician el crecimiento. Estas lluvias tardías eran indispensables para la maduración del grano antes de la siega; sin ellas, las cosechas se marchitarían. La palabra transmite urgencia agrícola: el sustento del labrador depende de esta bendición final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3798', 'spa', 'Tarde, atardecer — la última parte del día, desde media tarde hasta el anochecer.', 'Tarde, atardecer — la última parte del día, desde media tarde hasta el anochecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3799', 'spa', 'Apariencia, aspecto exterior; rostro, semblante; la forma visible de una persona o cosa', 'Esta palabra se refiere a cómo se presenta algo visualmente: su aspecto exterior, rostro o semblante. Jesús advierte contra juzgar «según la apariencia» (Jn 7:24), contrastando la evaluación superficial con el juicio justo. Puede designar el rostro mismo, como cuando Lázaro sale de la tumba con un paño atado sobre su rostro (Jn 11:44), o la apariencia gloriosa del Cristo resucitado cuyo rostro resplandecía como el sol (Ap 1:16). El término subraya la dimensión visible y externa, que puede revelar una verdad más profunda o engañar si se toma como la realidad completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3800', 'spa', 'Paga, salario, soldada; asignación militar; figuradamente, la consecuencia merecida de los propios actos.', 'Originalmente un término militar que designaba la ración o paga del soldado, esta palabra porta tanto peso literal como teológico en el Nuevo Testamento. Juan el Bautista dice a los soldados: ''Contentaos con vuestra paga'' (Lc 3:14), y Pablo pregunta: ''¿Quién sirve como soldado a sus propias expensas?'' (1 Co 9:7). La cumbre teológica es Ro 6:23: ''la paga del pecado es muerte'', donde la metáfora transforma el salario devengado del soldado en la consecuencia ineludible del pecado. Pablo también lo usa en sentido literal cuando afirma haber ''despojado a otras iglesias, recibiendo salario'' para su ministerio (2 Co 11:8). El español distingue entre ''paga'' y ''salario'', matices que reflejan bien la amplitud semántica del término griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3801', 'spa', 'ser, existir (entrada variante de G3603; formas adicionales de εἰμί)', 'Esta entrada duplica G3603 y recoge formas adicionales del verbo copulativo y existencial εἰμί. La extrema irregularidad de su paradigma a través de los dialectos griegos (eólico ἔμμι, cretense ἠμί, dórico ἐντί, etc.) explica la existencia de múltiples entradas en Strong. Su significado central permanece invariable: existencia, identidad, posesión y la función copulativa que une sujeto y predicado. Ningún verbo es más esencial para la gramática griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3802', 'spa', 'atrapar, tender una trampa, engañar para capturar', 'Este verbo significa atrapar o tender una trampa a alguien, generalmente mediante astucia o engaño. Mateo lo utiliza para describir la estrategia deliberada de los fariseos de sorprender a Jesús en sus palabras. El término deriva de ''trampa'' (παγίς) y evoca la imagen de la caza: preparar una celada para capturar a la presa. La palabra implica intención calculada, no un desafío espontáneo, y sugiere que los tramperos ven a su objetivo como una presa adversaria que debe ser atrapada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3803', 'spa', 'Lazo, trampa; dispositivo para atrapar presas, usado metafóricamente de peligros espirituales y ardides del diablo.', 'Sustantivo femenino que significa lazo o trampa, derivado de πήγνυμι (fijar, clavar). Aunque su sentido literal remite a un artilugio de caza, todas las apariciones neotestamentarias son metafóricas y describen peligros espirituales ocultos que atrapan repentinamente al desprevenido. Lc 21:35 advierte que el día del Señor vendrá ''como un lazo'' sobre toda la tierra. Ro 11:9 cita el Salmo 69:22, convirtiendo la mesa de los adversarios de Israel en una trampa. Las Epístolas Pastorales alertan sobre el ''lazo del diablo'' que atrapa al soberbio (1 Ti 3:7; 2 Ti 2:26) y la trampa de los deseos insensatos (1 Ti 6:9). El español ''trampa'' y ''lazo'' transmiten con precisión el elemento de peligro encubierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3804', 'spa', 'El sustantivo πάθημα posee dos sentidos claramente distintos en el Nuevo Testamento. En su uso dominante (catorce apariciones), designa sufrimiento y ', 'El sustantivo πάθημα posee dos sentidos claramente distintos en el Nuevo Testamento. En su uso dominante (catorce apariciones), designa sufrimiento y aflicción, sobre todo los padecimientos de Cristo y la participación del creyente en ellos. Pablo escribe que ''los sufrimientos del tiempo presente no son comparables con la gloria venidera'' (Ro 8:18) y habla de ''la comunión de sus padecimientos'' (Fil 3:10). Pero en dos pasajes paulinos, πάθημα gira para denotar pasiones o deseos pecaminosos que operan en el cuerpo humano: ''las pasiones de los pecados'' que obraban en nuestros miembros (Ro 7:5) y ''los que son de Cristo han crucificado la carne con sus pasiones y deseos'' (Gá 5:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3805', 'spa', 'sujeto a sufrimiento, capaz de padecer dolor o pasión', 'Este adjetivo describe a alguien o algo capaz de sufrir o experimentar pasión. En Hechos, aparece en la declaración de Pablo de que el Cristo debía ser ''sujeto a padecimiento.'' El término puede denotar susceptibilidad a influencias externas, pasividad ante el cambio o vulnerabilidad al dolor. Se opone a ἀπαθής (impasible, incapaz de sufrir). La palabra subraya la vulnerabilidad y la humanidad: la capacidad de ser afectado, de sentir dolor, de soportar aflicción, cualidades inherentes a la verdadera naturaleza humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3806', 'spa', 'pasión, deseo intenso, emoción desordenada; especialmente concupiscencias degradantes y afectos vergonzosos', 'Derivado de πάσχω (''padecer''), este término designaba originalmente cualquier experiencia sufrida por una persona, pero evolucionó para referirse a pasiones o emociones intensas, sobre todo las desordenadas o vergonzosas. Pablo lo emplea para describir las pasiones degradantes que resultan de la idolatría (Ro 1:26), los deseos pecaminosos que deben ser mortificados (Col 3:5) y la concupiscencia propia de quienes no conocen a Dios (1 Ts 4:5). El vocablo no describe simplemente un sentimiento fuerte, sino el ser dominado por deseos que degradan y esclavizan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3807', 'spa', 'pedagogo, guardián, tutor; esclavo encargado de supervisar la conducta de un niño y acompañarlo a la escuela', 'En el mundo grecorromano, el pedagogo era un esclavo del hogar responsable de la supervisión moral del niño y de escoltarlo a la escuela; no era el maestro principal, sino un custodio y guía. Pablo emplea esta imagen con fuerza: los corintios podrán tener innumerables ''tutores'' en Cristo, pero solo un padre (1 Co 4:15). Más célebre aún es su descripción de la ley mosaica como un pedagogo que nos guio hasta la venida de Cristo (Gá 3:24-25). Una vez llegada la fe, ya no estamos bajo este custodio. La metáfora capta tanto la protección como la limitación: necesaria por un tiempo, pero destinada a ser superada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3808', 'spa', 'muchachito, niño pequeño, chiquillo', 'Este sustantivo diminutivo designa a un niño pequeño o chiquillo. En el Evangelio de Juan, identifica al muchacho que proporciona cinco panes de cebada y dos peces para que Jesús los multiplique. La forma diminutiva enfatiza la juventud y la pequeña estatura del niño, lo cual acentúa el contraste con la enorme multitud que debía ser alimentada. El término transmite tanto afecto como insignificancia: un simple muchachito con un almuerzo modesto se convierte en el instrumento de un milagro que alimenta a miles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3809', 'spa', 'Disciplina, corrección o formación; el proceso formativo mediante el cual un padre o Dios moldea el carácter con instrucción y corrección', 'Παιδεία es una de las grandes palabras de la cultura griega antigua, que abarca todo el proceso de crianza y formación de una persona. En el Nuevo Testamento, sin embargo, se concentra en dos usos estrechamente relacionados pero distinguibles. En Hebreos 12:5-11, el autor desarrolla una extensa metáfora de Dios como padre que disciplina a sus hijos: dolorosa en el momento, pero que produce el fruto apacible de la justicia. Efesios 6:4 instruye a los padres a criar a sus hijos «en la disciplina y amonestación del Señor». Mientras tanto, 2 Timoteo 3:16 habla de la Escritura como útil «para la instrucción en justicia», enfatizando el aspecto formativo y educativo más que la corrección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3811', 'spa', 'Disciplinar, castigar; entrenar, educar, instruir — pedagogía tanto correctiva como formativa.', 'Disciplinar, castigar; entrenar, educar, instruir — pedagogía tanto correctiva como formativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3812', 'spa', 'desde la niñez, desde que era niño', 'Este adverbio indica origen temporal, significando ''desde la niñez'' o ''desde que era niño''. Marcos lo emplea en el relato del muchacho poseído por un espíritu mudo, cuyo padre informa que la aflicción lo ha atormentado desde la primera infancia. El término subraya la duración y el inicio temprano: no se trata de un problema reciente sino de una lucha que ha abarcado toda la vida. Transmite la profundidad del sufrimiento cuando se asocia con la infancia, una condición que ha arrebatado el desarrollo normal y la alegría de la juventud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3813', 'spa', 'Niño pequeño, infante o criatura; diminutivo de παῖς, usado especialmente del niño Jesús y de los niños en los Evangelios', 'Diminutivo de παῖς («niño, siervo»), παιδίον evoca ternura y vulnerabilidad. Aparece de manera memorable en los relatos de la infancia: los magos buscan «al niño» en Belén (Mt 2:8-14) y Simeón toma al niño Jesús en sus brazos en el Templo (Lc 2:27). Jesús coloca a un παιδίον en medio de los discípulos como modelo de la humildad propia del reino (Mt 18:2-5), y en Juan 16:21 la angustia de la mujer se convierte en gozo cuando nace su criatura. El término también aparece en Hebreos 2:13-14 para describir a aquellos con quienes Cristo comparte carne y sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3814', 'spa', 'Criada, esclava; una joven sirvienta o sierva doméstica en un hogar.', 'Criada, esclava; una joven sirvienta o sierva doméstica en un hogar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3815', 'spa', 'jugar, divertirse, participar en recreación o jolgorio', 'Este verbo designa actividad lúdica, ya sea recreación inocente, celebración o, en sentido negativo, jolgorio frívolo. Pablo cita la descripción de la Septuaginta sobre la celebración idolátrica de Israel en el Sinaí: ''El pueblo se sentó a comer y a beber, y se levantó a jugar''. En ese contexto, ''jugar'' conlleva connotaciones negativas de desenfreno asociado con la adoración de ídolos. La palabra puede describir juegos infantiles o danzas festivas de adultos, pero aquí sugiere una conducta incompatible con la adoración al Dios verdadero. Evoca un abandono despreocupado al placer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3816', 'spa', 'Niño o siervo; una persona joven (niño o niña) o alguien que sirve a un amo, incluyendo al siervo escogido de Dios.', 'Niño o siervo; una persona joven (niño o niña) o alguien que sirve a un amo, incluyendo al siervo escogido de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G3817', 'spa', 'Golpear, herir; asestar un golpe con la mano, un arma o un aguijon, frecuentemente en contextos de violencia o maltrato.', 'Verbo que significa golpear o herir, ya sea con la mano, un arma o un aguijon. En los relatos de la Pasion, describe los maltratos que Jesus sufrio: lo golpearon durante sus juicios exigiendole que profetizara quien lo habia herido (Mt 26:68; Lc 22:64). Marcos 14:47 y Juan 18:10 lo emplean para el discipulo que hirio al siervo del sumo sacerdote, cortandole la oreja, una de las pocas acciones narradas en los cuatro Evangelios. Apocalipsis 9:5 lo extiende al aguijon de las langostas-escorpiones. El termino implica contacto fisico directo y contundente.');